/* ===== spa-navigation/drilldown/widget-mount/p1.js ===== */
  function resolveDrilldownChartSlotCaption(config) {
    const explicit = nonEmptyString(config?.title, config?.label);
    if (explicit) return explicit;
    const by = nonEmptyString(
      Array.isArray(config?.compositionBy) ? config.compositionBy[0] : "",
      config?.by,
    );
    return by ? `按${by}构成` : "";
  }

  function createDrilldownChartSlotCaption(title) {
    const text = nonEmptyString(title);
    if (!text) return null;
    const el = document.createElement("div");
    el.className = "access-drilldown-chart-slot-caption";
    el.textContent = text;
    return el;
  }

  function resetDrilldownChartSlotHost(host, title) {
    host.replaceChildren();
    const caption = createDrilldownChartSlotCaption(title);
    if (caption) host.appendChild(caption);
  }

  function drilldownChartTag(chartKind, tabId) {
    const explicit = String(chartKind || "").trim().toLowerCase();
    const fallback = normalizeTabId(tabId) === "trend" ? "line" : "bar";
    const kind = explicit || fallback;
    const supported = new Set([
      "line",
      "area",
      "trend",
      "column",
      "bar",
      "scatter",
      "pie",
      "donut",
      "rose",
      "radar",
      "ranking",
      "boxplot",
    ]);
    if (!supported.has(kind)) return "";
    return `mei-chart-${kind}`;
  }

  const DRILLDOWN_CHART_SCRIPT_BY_TAG = {
    "mei-chart-line": "/workspace-components/chart/echarts/line.js",
    "mei-chart-area": "/workspace-components/chart/echarts/area.js",
    "mei-chart-trend": "/workspace-components/chart/echarts/trend.js",
    "mei-chart-column": "/workspace-components/chart/echarts/column.js",
    "mei-chart-bar": "/workspace-components/chart/echarts/bar.js",
    "mei-chart-scatter": "/workspace-components/chart/echarts/scatter.js",
    "mei-chart-pie": "/workspace-components/chart/echarts/pie.js",
    "mei-chart-donut": "/workspace-components/chart/echarts/donut.js",
    "mei-chart-rose": "/workspace-components/chart/echarts/rose.js",
    "mei-chart-radar": "/workspace-components/chart/echarts/radar.js",
    "mei-chart-ranking": "/workspace-components/chart/echarts/ranking.js",
    "mei-chart-boxplot": "/workspace-components/chart/echarts/boxplot.js",
  };

  const DRILLDOWN_TABLE_SCRIPT = "/workspace-components/cockpit/data-table.js";
  // v2 标签 + 新 URL：旧 CE 无法复用「锁成红/黄/蓝」的模块
  const DRILLDOWN_FILTER_BAR_SCRIPT =
    "/workspace-components/dataset/filter-bar.js?v=filter-scroll-20260727a";
  const DRILLDOWN_FILTER_BAR_TAG = "mei-dataset-filter-bar-v2";
  const DRILLDOWN_ECHARTS_VENDOR_SCRIPT = "/workspace-components/vendor/echarts/echarts.min.js";
  const DRILLDOWN_CUSTOM_ELEMENT_WAIT_MS = 8000;

  async function waitForCustomElementTag(tagName) {
    const tag = String(tagName || "").trim().toLowerCase();
    if (!tag) return false;
    if (customElements.get(tag)) return true;
    try {
      await Promise.race([
        customElements.whenDefined(tag),
        new Promise((_, reject) => {
          setTimeout(
            () => reject(new Error("custom element define timeout: " + tag)),
            DRILLDOWN_CUSTOM_ELEMENT_WAIT_MS,
          );
        }),
      ]);
    } catch (_) {
      /* fall through */
    }
    return Boolean(customElements.get(tag));
  }

  async function ensureDrilldownChartRegistered(tagName) {
    const tag = String(tagName || "").trim().toLowerCase();
    if (!tag) return false;
    if (customElements.get(tag)) return true;
    const scriptPath = DRILLDOWN_CHART_SCRIPT_BY_TAG[tag];
    if (!scriptPath) return false;
    await loadScript(scriptPath, {
      module: true,
      persistentKey: scriptPath,
      softFail: false,
    });
    return waitForCustomElementTag(tag);
  }

  async function ensureDrilldownChartVendorLoaded() {
    if (window.echarts) return true;
    await loadScript(DRILLDOWN_ECHARTS_VENDOR_SCRIPT, {
      persistentKey: DRILLDOWN_ECHARTS_VENDOR_SCRIPT,
      softFail: false,
    });
    return Boolean(window.echarts);
  }

  async function ensureDrilldownTableRegistered() {
    const tag = "mei-cockpit-data-table";
    if (customElements.get(tag)) return true;
    await loadScript(DRILLDOWN_TABLE_SCRIPT, {
      module: true,
      persistentKey: DRILLDOWN_TABLE_SCRIPT,
      softFail: false,
    });
    return waitForCustomElementTag(tag);
  }

  async function ensureDrilldownFilterBarRegistered() {
    const tag = DRILLDOWN_FILTER_BAR_TAG;
    if (customElements.get(tag)) return true;
    await loadScript(DRILLDOWN_FILTER_BAR_SCRIPT, {
      module: true,
      persistentKey: DRILLDOWN_FILTER_BAR_SCRIPT,
      softFail: false,
    });
    return waitForCustomElementTag(tag);
  }

  async function prefetchStructuredDrilldownWidgets(config) {
    const tasks = [ensureDrilldownTableRegistered(), ensureDrilldownFilterBarRegistered()];
    const chartTags = new Set();
    const slotsByZone =
      config?.slotsByZone && typeof config.slotsByZone === "object" && !Array.isArray(config.slotsByZone)
        ? config.slotsByZone
        : {};
    Object.values(slotsByZone).forEach((zoneSlots) => {
      if (!Array.isArray(zoneSlots)) return;
      zoneSlots.forEach((slot) => {
        if (slot?.component !== "chart") return;
        const tag = drilldownChartTag(slot.chartKind, slot.id);
        if (tag) chartTags.add(tag);
      });
    });
    if (!chartTags.size && Array.isArray(config?.chartSlots)) {
      config.chartSlots.forEach((slot) => {
        const tag = drilldownChartTag(slot?.chartKind, slot?.id);
        if (tag) chartTags.add(tag);
      });
    }
    chartTags.forEach((tag) => tasks.push(ensureDrilldownChartRegistered(tag)));
    if (chartTags.size > 0) {
      tasks.push(ensureDrilldownChartVendorLoaded());
    }
    await Promise.all(tasks);
  }

  function buildDrilldownChartProps(detail, config, tabId) {
    const tableProps = buildDrilldownTableProps(detail, config);
    if (!tableProps) return null;
    const chartTag = drilldownChartTag(config?.chartKind, tabId);
    if (!chartTag) return null;
    const columns = Array.isArray(config?.columns) ? config.columns : [];
    const normalizedKind = explainMetricKind(config, tabId);
    const cardMetricId = nonEmptyString(
      detail?.metric_id,
      detail?.__mei_runtime_ref?.metric_id,
      config?.tableMetricId,
    );
    const chartMetricId = nonEmptyString(
      config?.tableMetricId,
      resolveCompositionScopedMetricId(cardMetricId, tabId),
      config?.runtimeRef?.metricId,
      config?.runtimeRef?.metric_id,
    );
    const dedicatedChartMetric = isDedicatedExplainMetricId(chartMetricId, {
      supportRole: config?.supportRole,
    });
    const runtimeRefConfig =
      config?.runtimeRef && typeof config.runtimeRef === "object" ? config.runtimeRef : {};
    const dedicatedDatasetId = config?.structuredBoard
      ? nonEmptyString(
          tableProps.dataset?.__mei_runtime_ref?.dataset_id,
          runtimeRefConfig.datasetId,
          runtimeRefConfig.dataset_id,
        )
      : nonEmptyString(
          runtimeRefConfig.datasetId,
          runtimeRefConfig.dataset_id,
          tableProps.dataset?.__mei_runtime_ref?.dataset_id,
        );
    const chartDataset =
      dedicatedChartMetric && chartMetricId
        ? {
            __mei_runtime_ref: {
              kind: "metric",
              metric_id: chartMetricId,
              dataset_id: dedicatedDatasetId,
              scene_id: nonEmptyString(
                runtimeRefConfig.sceneId,
                runtimeRefConfig.scene_id,
                tableProps.dataset?.__mei_runtime_ref?.scene_id,
              ),
              scene_path: nonEmptyString(
                runtimeRefConfig.scenePath,
                runtimeRefConfig.scene_path,
                tableProps.dataset?.__mei_runtime_ref?.scene_path,
              ),
            },
          }
        : tableProps.dataset;
    const compositionField = nonEmptyString(
      compositionFieldForTab(config, tabId),
      Array.isArray(config?.compositionBy) ? config.compositionBy[0] : "",
      config?.by,
      columns[0],
    );
    const xField =
      normalizedKind === "trend" ? "month" : normalizedKind === "composition" ? compositionField : columns[0] || "label";
    const yField = "value";
    const mapping = buildDefaultCompositionMapping(config, detail, xField, yField);
    return {
      chartTag,
      props: {
        // Slot caption owns the visible title; chart shell .head would duplicate it.
        title: "",
        data: chartDataset,
        _mei: tableProps._mei,
        query_state: tableProps.query_state,
        supportRole: config?.supportRole,
        labelField: compositionField,
        topN: positiveInt(config?.top_n, config?.topN),
        mapping,
        selection_filter_encode: nonEmptyString(
          config?.selection_filter_encode,
          config?.selectionFilterEncode,
        ) || undefined,
        category_order:
          Array.isArray(config?.category_order) && config.category_order.length > 0
            ? config.category_order
            : Array.isArray(config?.categoryOrder) && config.categoryOrder.length > 0
              ? config.categoryOrder
              : undefined,
        ...buildAnalyticsChartPresentationProps(config, { mapping }),
      },
    };
  }

  async function mountAnalyticsChartSlot(root, detail, config, tabId, hostOverride = null) {
    const kind = explainMetricKind(config, tabId);
    const supportRole = nonEmptyString(config?.supportRole, config?.slotByTab?.[normalizeTabId(tabId)]?.supportRole);
    const cardMetricId = nonEmptyString(
      detail?.metric_id,
      detail?.__mei_runtime_ref?.metric_id,
      config?.tableMetricId,
    );
    const chartMetricId = nonEmptyString(
      config?.tableMetricId,
      resolveCompositionScopedMetricId(cardMetricId, tabId),
      config?.runtimeRef?.metricId,
      config?.runtimeRef?.metric_id,
    );
    const dedicatedChartMetric = isDedicatedExplainMetricId(chartMetricId, {
      supportRole: config?.supportRole ?? supportRole,
    });
    const sharedQueryStateId = nonEmptyString(
      config?.queryStateId,
      detail?.query_state_id,
      detail?.queryStateId,
    );
    if (
      kind === "composition" ||
      supportRole === "composition" ||
      kind === "trend" ||
      supportRole === "trend" ||
      isVerifiedShareCompositionTab(tabId, config)
    ) {
      // 查实占比：始终从当前明细 __scalar_rowset__ 重算（与表同一真源），
      // 禁止走独立 composition/dataframe 服务端聚合。
      if (isVerifiedShareCompositionTab(tabId, config)) {
        return mountDerivedDrilldownContent(root, detail, config, tabId, hostOverride);
      }
      // 其它构成/趋势：无筛选走服务端 explain；有筛选则基于明细客户端重聚合。
      const hasFilters = hasActiveDrilldownQueryFilters(sharedQueryStateId);
      if (!hasFilters && dedicatedChartMetric) {
        if (await mountDrilldownChart(root, detail, config, tabId, hostOverride)) {
          return true;
        }
      }
      return mountDerivedDrilldownContent(root, detail, config, tabId, hostOverride);
    }
    return mountDrilldownChart(root, detail, config, tabId, hostOverride);
  }

  async function mountDrilldownChart(root, detail, config, tabId, hostOverride = null) {
    const host =
      hostOverride instanceof HTMLElement
        ? hostOverride


/* ===== spa-navigation/drilldown/widget-mount/p2.js ===== */
        : root.querySelector('[data-drilldown-table-host="true"]');
    if (!(host instanceof HTMLElement)) {
      return false;
    }
    const chart = buildDrilldownChartProps(detail, config, tabId);
    if (!chart) return false;
    const registered = await ensureDrilldownChartRegistered(chart.chartTag);
    if (!registered) return false;
    resetDrilldownChartSlotHost(host, resolveDrilldownChartSlotCaption(config));
    const node = document.createElement(chart.chartTag);
    node.dataset.props = JSON.stringify(chart.props);
    host.appendChild(node);
    return true;
  }

  async function mountDrilldownTable(root, detail, config, hostOverride = null) {
    const host =
      hostOverride instanceof HTMLElement
        ? hostOverride
        : root.querySelector('[data-drilldown-table-host="true"]');
    if (!(host instanceof HTMLElement)) {
      return false;
    }
    const props = applyAnalyticsTableRowDrilldown(buildDrilldownTableProps(detail, config), config, detail);
    if (!props) {
      recordPopupDebugIssue({
        level: "error",
        message: "未解析到下钻明细表所需 scene_id 或 dataset_id",
        phase: "table_mount_setup",
        detail,
        config,
        datasetId: resolveDrilldownDatasetId(detail, config),
        metricId: nonEmptyString(detail?.metric_id, detail?.__mei_runtime_ref?.metric_id),
        root,
      });
      return false;
    }
    const registered = await ensureDrilldownTableRegistered();
    if (!registered) {
      recordPopupDebugIssue({
        level: "error",
        message: "未注册 mei-cockpit-data-table（可能是组件脚本加载失败）",
        phase: "table_mount_register",
        detail,
        config,
        datasetId: resolveDrilldownDatasetId(detail, config),
        metricId: nonEmptyString(detail?.metric_id, detail?.__mei_runtime_ref?.metric_id),
        root,
      });
      return false;
    }
    host.replaceChildren();
    const table = document.createElement("mei-cockpit-data-table");
    table.dataset.props = JSON.stringify(props);
    host.appendChild(table);
    return true;
  }

  function buildFilterColumnCatalog(config, tableProps) {
    const schemaFields = Array.isArray(config?.filterSchema?.fields) ? config.filterSchema.fields : [];
    const detailFields = Array.isArray(config?.detailSlot?.fields) ? config.detailSlot.fields : [];
    const tableColumns = Array.isArray(tableProps?.columns) ? tableProps.columns : [];
    const fallbackColumns = Array.isArray(config?.columns) ? config.columns : [];
    const allowExtra =
      config?.filterSchema?.allowExtra === true || config?.filterSchema?.allow_extra === true;
    const byColumn = new Map();
    // 作者声明字段优先（含 control / contains_any 等），并占 catalog 前部 → 默认预置取前 N 个
    for (const field of schemaFields) {
      const mapped = mapAnalyticsFilterField(field);
      const column = nonEmptyString(mapped.column, mapped.key);
      if (!column) continue;
      byColumn.set(column, mapped);
    }
    // 作者声明 allow_extra=false 时只保留 fields，禁止表列（旧「监督类别」/行权类别）抢预置位。
    // 完全没有 filter_schema 时仍回退表列（兼容未声明过滤的看板）。
    const authorSchemaPresent = Boolean(
      config?.filterSchema &&
        (schemaFields.length > 0 ||
          config.filterSchema.allowExtra === false ||
          config.filterSchema.allow_extra === false ||
          config.filterSchema.presetFilterCount != null ||
          config.filterSchema.preset_filter_count != null ||
          config.filterSchema.defaultCollapsed === false ||
          config.filterSchema.default_collapsed === false),
    );
    if (allowExtra || (schemaFields.length === 0 && !authorSchemaPresent)) {
      for (const raw of [...detailFields, ...tableColumns, ...fallbackColumns]) {
        const column = String(raw || "").trim();
        if (!column || byColumn.has(column) || !isFilterableDetailColumn(column)) continue;
        const control = inferDefaultControlForColumn(column);
        byColumn.set(column, {
          key: column,
          label: column,
          column,
          control,
          options_from: control === "text" ? undefined : "rowset",
          options_field: column,
          visible: true,
        });
      }
    }
    return Array.from(byColumn.values());
  }

  function isFilterableDetailColumn(column) {
    const name = String(column || "").trim();
    if (!name) return false;
    if (/^序号$/.test(name)) return false;
    if (/条数$|金额$|人数$|^value$/i.test(name)) return false;
    if (/^\d{4}$/.test(name)) return false;
    if (/^month$/i.test(name)) return false;
    return true;
  }

  /** 自动并入的表列：给合理 control，否则无法拉 facet / 多选。 */
  function inferDefaultControlForColumn(column) {
    const name = String(column || "").trim();
    if (/时间$|日期$|年月/.test(name)) return "month_multi_select";
    if (/ID$|编号$|编码$/.test(name)) return "text";
    if (/描述$|说明$|内容$|意见$|表现形式$|存在的问题$/.test(name)) return "text";
    return "multi_select";
  }

  function mapAnalyticsFilterField(field) {
    const key = nonEmptyString(field.key, field.column);
    const column = nonEmptyString(field.column, field.key);
    const declaredOptions = Array.isArray(field.options) ? field.options : [];
    const authoredOptionsFrom = nonEmptyString(field.options_from, field.optionsFrom);
    // 已声明静态枚举时勿默认成 rowset，否则 additive 会走空 facet 并盖掉静态项。
    const optionsFrom =
      authoredOptionsFrom || (declaredOptions.length > 0 ? "static" : "rowset");
    // 风险等级等组合面值必须走 rowset facet，才能带计数并按计数排序；
    // 不要再注入无 count 的 static 组合列表。
    return {
      key,
      label: field.label || field.key || field.column,
      column,
      control: nonEmptyString(field.control, field.type) || undefined,
      operator: nonEmptyString(field.operator, field.default_operator, field.defaultOperator),
      options_from: optionsFrom,
      options_field: nonEmptyString(field.options_field, field.optionsField, field.column),
      options: declaredOptions.length > 0 ? declaredOptions : undefined,
      placeholder: nonEmptyString(field.placeholder),
      visible: field.visible !== false,
    };
  }

  function buildAnalyticsFilterBarProps(config, detail) {
    const tableProps = buildDrilldownTableProps(detail, config) || {};
    const filterSchema = config?.filterSchema || {};
    // 全列候选 = 明细表列 ∪ 作者 filter_schema.fields；作者字段排前，默认预置取前 ~3 个
    const columnCatalog = buildFilterColumnCatalog(config, tableProps);
    const presetFilterCount = Math.max(
      0,
      Number(
        filterSchema.presetFilterCount ??
          filterSchema.preset_filter_count ??
          filterSchema.defaultPresetCount ??
          3,
      ) || 0,
    );
    const rowsetDatasetId = nonEmptyString(
      filterSchema.rowsetDatasetId,
      config?.filterSchema?.rowsetDatasetId,
      tableProps?.dataset?.__mei_runtime_ref?.dataset_id,
      tableProps?.dataset?.id,
    );
    // issue_handling_list 等是 metric 派生 rowset：无 metric_id 时 rows/facets 皆空。
    // filter-bar 选项请求必须复用明细表的 metric runtime ref（含 ::__scalar_rowset__）。
    const tableRuntimeRef =
      tableProps?.dataset?.__mei_runtime_ref && typeof tableProps.dataset.__mei_runtime_ref === "object"
        ? tableProps.dataset.__mei_runtime_ref
        : {};
    const filterMetricId = nonEmptyString(
      tableRuntimeRef.metric_id,
      tableRuntimeRef.metricId,
      typeof resolveCardMetricRowsetId === "function"
        ? resolveCardMetricRowsetId(
            nonEmptyString(config?.tableMetricId, config?.metricId, detail?.metric_id),
          )
        : "",
    );
    const filterRuntimeRef = rowsetDatasetId
      ? {
          ...tableRuntimeRef,
          kind: filterMetricId ? "metric" : nonEmptyString(tableRuntimeRef.kind, "data") || "data",
          dataset_id: rowsetDatasetId,
          ...(filterMetricId ? { metric_id: filterMetricId } : {}),
          scene_id: nonEmptyString(
            tableRuntimeRef.scene_id,
            config?.runtimeSceneId,
            config?.hostSceneId,
            config?.sceneId,
          ),
          scene_path: nonEmptyString(tableRuntimeRef.scene_path, config?.runtimeSceneFile),
        }
      : null;
    // Seed only — 不要把 tableProps 里误混的 identity 当种子（table 已拆分）。
    const seedFilters = (() => {
      const seed = tableProps?.default_filters;
      if (seed && typeof seed === "object" && !Array.isArray(seed)) return seed;
      const fromDetail = detail?.default_filters;
      if (fromDetail && typeof fromDetail === "object" && !Array.isArray(fromDetail)) return fromDetail;
      const fromParams = config?.params?.default_filters;
      if (fromParams && typeof fromParams === "object" && !Array.isArray(fromParams)) return fromParams;
      return null;
    })();
    const scopeFilters = (() => {
      const fromTable = tableProps?.scope_filters;
      if (fromTable && typeof fromTable === "object" && !Array.isArray(fromTable)) return fromTable;
      const fromConfig = config?.scopeFilters || config?.scope_filters;
      if (fromConfig && typeof fromConfig === "object" && !Array.isArray(fromConfig)) return fromConfig;
      const fromDetail = detail?.scope_filters || detail?.scopeFilters;
      if (fromDetail && typeof fromDetail === "object" && !Array.isArray(fromDetail)) return fromDetail;
      return null;
    })();
    const identityFilters = (() => {
      const fromTable = tableProps?.drilldown_filters;
      if (fromTable && typeof fromTable === "object" && !Array.isArray(fromTable)) return fromTable;
      const fromDetail = detail?.drilldown_filters;
      if (fromDetail && typeof fromDetail === "object" && !Array.isArray(fromDetail)) return fromDetail;
      return null;
    })();
    return {
      mode: "additive",
      live: false,
      title: nonEmptyString(filterSchema.title) || "筛选条件",
      default_collapsed: Boolean(filterSchema.defaultCollapsed),
      allow_extra: filterSchema.allowExtra === true,
      preset_filter_count: presetFilterCount,
      query_state: nonEmptyString(
        config?.queryStateId,
        detail?.query_state_id,
        detail?.queryStateId,
        config?.tableMetricId ? `drilldown::${config.tableMetricId}` : "",
        config?.metricId ? `drilldown::${config.metricId}` : "",
      ) || undefined,
      default_filters: seedFilters || undefined,
      scope_filters: scopeFilters || undefined,
      drilldown_filters: identityFilters || undefined,
      rowset_dataset_id: rowsetDatasetId || undefined,
      dataset: filterRuntimeRef
        ? {
            id: rowsetDatasetId,
            shape: filterMetricId ? "dataframe" : "table",
            __mei_runtime_ref: filterRuntimeRef,
          }
        : tableProps.dataset,
      data: filterRuntimeRef
        ? {
            id: rowsetDatasetId,
            __mei_runtime_ref: filterRuntimeRef,
          }
        : tableProps.dataset,
      _mei: {
        ...(tableProps._mei && typeof tableProps._mei === "object" ? tableProps._mei : {}),
        filter_layers: {
          seed: seedFilters || {},
          scope: scopeFilters || {},
          identity: identityFilters || {},
        },
      },
      column_catalog: columnCatalog,
      fields: columnCatalog,
    };
  }

  async function mountAnalyticsFilterBar(root, detail, config, hostOverride = null) {
    const host =
      hostOverride instanceof HTMLElement
        ? hostOverride
        : root.querySelector('[data-drilldown-filter-host="true"]');
    if (!(host instanceof HTMLElement)) return false;
    const filterProps = buildAnalyticsFilterBarProps(config, detail);
    const fieldCount = Array.isArray(filterProps?.column_catalog)
      ? filterProps.column_catalog.length
      : Array.isArray(filterProps?.fields)
        ? filterProps.fields.length
        : 0;
    host.toggleAttribute("hidden", fieldCount === 0);
    if (fieldCount === 0) {
      host.replaceChildren();
      return false;
    }
    const registered = await ensureDrilldownFilterBarRegistered();
    if (!registered) return false;
    host.replaceChildren();
    const node = document.createElement("mei-dataset-filter-bar-v2");
    node.dataset.props = JSON.stringify(filterProps);
    host.appendChild(node);
    return true;
  }

  function cleanupAnalyticsDrilldownWatcher(root) {
    if (!(root instanceof HTMLElement)) return;
    const cleanup = root.__meiAnalyticsQueryStateCleanup;
    if (typeof cleanup === "function") {
      cleanup();
    }
    root.__meiAnalyticsQueryStateCleanup = null;
  }

  async function remountStructuredAnalyticsChartZones(root, detail, config, resolveZoneHost) {
    const slotZones = sceneShellZonesByRole(config?.sceneShell, "slots");
    let ok = true;
    for (const zone of slotZones) {
      const zoneSlots = Array.isArray(config?.slotsByZone?.[zone.id]) ? config.slotsByZone[zone.id] : [];
      if (!zoneSlots.length || !zoneSlots.every((slot) => slot.component === "chart")) {
        continue;
      }
      const host =
        typeof resolveZoneHost === "function"
          ? resolveZoneHost(zone.id)
          : root.__meiStructuredZoneHosts?.[zone.id];
      if (!(host instanceof HTMLElement)) {
        ok = false;
        continue;
      }
      const zoneOk = await mountAnalyticsChartSlots(root, detail, config, zoneSlots, host);
      ok = ok && zoneOk;
    }
    return ok;
  }

  async function remountStructuredAnalyticsDetailZones(root, detail, config, resolveZoneHost) {
    const slotZones = sceneShellZonesByRole(config?.sceneShell, "slots");
    let ok = true;
    for (const zone of slotZones) {
      const zoneSlots = Array.isArray(config?.slotsByZone?.[zone.id]) ? config.slotsByZone[zone.id] : [];
      if (!zoneSlots.length || zoneSlots.every((slot) => slot.component === "chart")) {
        continue;
      }
      const host =
        typeof resolveZoneHost === "function"
          ? resolveZoneHost(zone.id)
          : root.__meiStructuredZoneHosts?.[zone.id];
      if (!(host instanceof HTMLElement)) {
        ok = false;
        continue;
      }
      const zoneOk = await mountStructuredSlotZone(root, detail, config, zone, host);
      ok = ok && zoneOk;
    }
    return ok;
  }

  function bindAnalyticsChartsQueryStateRefresh(root, detail, config, resolveZoneHost) {
    cleanupAnalyticsDrilldownWatcher(root);
    const queryStateId = nonEmptyString(config?.queryStateId, detail?.query_state_id, detail?.queryStateId);
    if (!queryStateId) return;
    let refreshSeq = 0;
    const onQueryStateChange = (event) => {
      if (event?.detail?.id !== queryStateId) return;
      if (!(root instanceof HTMLElement) || root.hasAttribute("hidden")) return;
      const currentSeq = ++refreshSeq;
      // 明细表已 subscribeQueryState 自行刷新；此处若 remount 明细，会与进行中的
      // 过滤请求竞态（无过滤的旧请求后返回，盖掉筛选结果 → 看起来像过滤失效）。
      remountStructuredAnalyticsChartZones(root, detail, config, resolveZoneHost)
        .then((chartsOk) => {
          if (!chartsOk || currentSeq !== refreshSeq) return;
          dispatchPreviewUpdated("drilldown");
        })
        .catch((error) => {
          recordPopupDebugIssue({
            level: "error",
            message: String(error?.message || error || "分析型看板刷新失败"),
            phase: "analytics_chart_refresh_error",
            detail,
            config,
            root,
            stack: error?.stack || "",
          });
        });
    };
    window.addEventListener("mei:query-state-change", onQueryStateChange);
    root.__meiAnalyticsQueryStateCleanup = () => {
      window.removeEventListener("mei:query-state-change", onQueryStateChange);
    };
  }



/* ===== spa-navigation/drilldown/render-analytics.js ===== */
  async function mountAnalyticsChartSlots(root, detail, config, chartSlots, chartsHost) {
    const chartMounts = chartSlots.map(async (slot, index) => {
      const slotHost = chartsHost.querySelector(`[data-chart-slot-index="${index}"]`);
      if (slotHost instanceof HTMLElement && slot?.id) {
        slotHost.dataset.buildBoardSlot = String(slot.id);
      }
      const slotConfig = resolveDrilldownTabConfig(config, slot.id);
      const boardMetricId = nonEmptyString(config.tableMetricId);
      const chartMapping =
        slot.mapping && typeof slot.mapping === "object"
          ? slot.mapping
          : slotConfig.mapping && typeof slotConfig.mapping === "object"
            ? slotConfig.mapping
            : null;
      // 图表 composition 父级同样优先 board / popup 分析指标，勿用入口 KPI count。
      const cardMetricId = nonEmptyString(
        boardMetricId,
        resolvePopupPassedMetricId(detail, config),
        detail?.metric_id,
        detail?.__mei_runtime_ref?.metric_id,
      );
      const compositionMetricId = resolveCompositionScopedMetricId(cardMetricId, slot.id);
      const resolvedChartMetricId = nonEmptyString(
        isDedicatedExplainMetricId(slot.metricId, { supportRole: slot.supportRole })
          ? slot.metricId
          : "",
        compositionMetricId,
        slot.metricId,
        slotConfig.tableMetricId,
        boardMetricId,
      );
      const explainBy = nonEmptyString(
        slot.by?.[0],
        config.explainMetrics?.[slot.id]?.by,
        config.tabMetrics?.[slot.id]?.by,
        slotConfig.by,
      );
      const mergedConfig = {
        ...slotConfig,
        hasChartZone: config.hasChartZone,
        rowsetDatasetId: config.rowsetDatasetId,
        hostSceneId: config.hostSceneId,
        hostSceneFile: config.hostSceneFile,
        runtimeSceneId: config.runtimeSceneId,
        runtimeSceneFile: config.runtimeSceneFile,
        queryStateId: config.queryStateId,
        supportRole: nonEmptyString(slot.supportRole, slotConfig.supportRole, "composition"),
        tableMetricId: resolvedChartMetricId,
        chartKind: nonEmptyString(slot.chartKind, slotConfig.chartKind),
        topN: positiveInt(slot.topN, slot.top_n, slotConfig.topN, slotConfig.top_n),
        mapping: chartMapping,
        by: explainBy,
        compositionBy: explainBy
          ? [explainBy]
          : Array.isArray(slot.by) && slot.by.length > 0
            ? slot.by
            : Array.isArray(slotConfig.compositionBy)
              ? slotConfig.compositionBy
              : [],
        trendField: nonEmptyString(slot.trendField, slot.dateField, slotConfig.trendField),
        trendGrain: nonEmptyString(slot.grain, slotConfig.trendGrain),
        runtimeRef: {
          ...(slotConfig.runtimeRef && typeof slotConfig.runtimeRef === "object" ? slotConfig.runtimeRef : {}),
          kind: "metric",
          metricId: resolvedChartMetricId,
          metric_id: resolvedChartMetricId,
          datasetId: nonEmptyString(slot.datasetId, slotConfig?.runtimeRef?.datasetId),
          dataset_id: nonEmptyString(slot.datasetId, slotConfig?.runtimeRef?.dataset_id),
          sceneId: nonEmptyString(config.runtimeSceneId, config.hostSceneId, config.sceneId),
          scene_id: nonEmptyString(config.runtimeSceneId, config.hostSceneId, config.sceneId),
          scenePath: nonEmptyString(
            config.runtimeSceneFile,
            config.hostSceneFile,
            detail?.host_scene_file,
            detail?.scene_path,
          ),
          scene_path: nonEmptyString(
            config.runtimeSceneFile,
            config.hostSceneFile,
            detail?.host_scene_file,
            detail?.scene_path,
          ),
        },
      };
      if (await mountAnalyticsChartSlot(root, detail, mergedConfig, slot.id, slotHost)) {
        return true;
      }
      recordPopupDebugIssue({
        level: "warn",
        phase: "analytics_chart_mount_failed",
        message: `chart slot ${String(slot.id || "").trim() || "unknown"} mount returned false`,
        detail,
        config: mergedConfig,
        datasetId: mergedConfig.datasetId,
        metricId: mergedConfig.tableMetricId,
        root,
      });
      return false;
    });
    const results = await Promise.all(chartMounts);
    return chartSlots.length === 0 || results.every(Boolean);
  }

  async function renderAnalyticsDrilldownContent(root, detail, config) {
    applyDrilldownOverlayMeta(root, config);
    setDrilldownOverlayStatus(root, "loading");
    cleanupAnalyticsDrilldownWatcher(root);
    const chartsHost = root.querySelector('[data-drilldown-charts-host="true"]');
    const tableHost = root.querySelector('[data-drilldown-analytics-table-host="true"]');
    if (!(chartsHost instanceof HTMLElement) || !(tableHost instanceof HTMLElement)) {
      setDrilldownOverlayStatus(root, "error", {
        message: "分析型看板缺少图表或明细挂载节点",
        phase: "analytics_host_missing",
        detail,
        config,
      });
      return false;
    }
    chartsHost.replaceChildren();
    tableHost.replaceChildren();
    const chartSlots = Array.isArray(config?.chartSlots) ? config.chartSlots : [];
    chartSlots.forEach((slot, index) => {
      const slotEl = document.createElement("div");
      slotEl.className = "access-drilldown-analytics-chart-slot";
      slotEl.dataset.chartSlotIndex = String(index);
      chartsHost.appendChild(slotEl);
    });
    chartsHost.style.gridTemplateColumns =
      chartSlots.length > 1 ? `repeat(${chartSlots.length}, minmax(0, 1fr))` : "1fr";
    chartsHost.toggleAttribute("hidden", chartSlots.length === 0);

    try {
      const filterHost = root.querySelector(
        '[data-drilldown-body-mode="analytics"] [data-drilldown-filter-host="true"]',
      );
      await mountAnalyticsFilterBar(root, detail, config, filterHost);
      const detailSlot = config?.detailSlot;
      const detailTabConfig = detailSlot ? resolveDrilldownTabConfig(config, detailSlot.id) : config;
      const detailConfig = detailSlot
        ? {
            ...detailTabConfig,
            structuredBoard: config.structuredBoard,
            boardSceneId: config.boardSceneId,
            boardSceneFile: config.boardSceneFile,
            detailSlot,
            runtimeSceneId: nonEmptyString(config.runtimeSceneId, config.boardSceneId),
            runtimeSceneFile: nonEmptyString(config.runtimeSceneFile, config.boardSceneFile),
            tableMetricId: nonEmptyString(
              detailSlot.metricId,
              detailTabConfig.tableMetricId,
              config.tableMetricId,
              resolveDrilldownTableMetricId(detail, config),
            ),
            queryStateId: config.queryStateId,
            runtimeRef: {
              ...(detailTabConfig?.runtimeRef && typeof detailTabConfig.runtimeRef === "object"
                ? detailTabConfig.runtimeRef
                : {}),
              sceneId: nonEmptyString(
                config.runtimeSceneId,
                config.boardSceneId,
                config.hostSceneId,
                config.sceneId,
              ),
              scene_id: nonEmptyString(
                config.runtimeSceneId,
                config.boardSceneId,
                config.hostSceneId,
                config.sceneId,
              ),
              scenePath: nonEmptyString(
                config.runtimeSceneFile,
                config.boardSceneFile,
                config.hostSceneFile,
                detail?.host_scene_file,
                detail?.scene_path,
              ),
              scene_path: nonEmptyString(
                config.runtimeSceneFile,
                config.boardSceneFile,
                config.hostSceneFile,
                detail?.host_scene_file,
                detail?.scene_path,
              ),
            },
            pageSize: positiveInt(
              detailSlot.pageSize,
              detailSlot.page_size,
              detailTabConfig.pageSize,
              detailTabConfig.page_size,
              10,
            ),
            pagination: true,
            paginationMode: "server",
            columns: cloneArray(detailSlot.fields).length
              ? cloneArray(detailSlot.fields)
              : cloneArray(detailTabConfig.columns),
          }
        : config;
      const [chartsOk, tableOk] = await Promise.all([
        mountAnalyticsChartSlots(root, detail, config, chartSlots, chartsHost),
        mountDrilldownTable(root, detail, detailConfig, tableHost),
      ]);
      if (!tableOk || !chartsOk) {
        setDrilldownOverlayStatus(root, "error", {
          message: `分析型看板挂载失败：charts=${chartsOk} table=${tableOk}`,
          phase: "analytics_mount_failed",
          detail,
          config,
        });
        return false;
      }
      const queryStateId = nonEmptyString(config?.queryStateId, detail?.query_state_id, detail?.queryStateId);
      if (queryStateId) {
        let refreshSeq = 0;
        const onQueryStateChange = (event) => {
          if (event?.detail?.id !== queryStateId) return;
          if (!(root instanceof HTMLElement) || root.hasAttribute("hidden")) return;
          const currentSeq = ++refreshSeq;
          mountAnalyticsChartSlots(root, detail, config, chartSlots, chartsHost)
            .then((ok) => {
              if (!ok || currentSeq !== refreshSeq) return;
              dispatchPreviewUpdated("drilldown");
            })
            .catch((error) => {
              recordPopupDebugIssue({
                level: "error",
                message: String(error?.message || error || "分析型下钻图表刷新失败"),
                phase: "analytics_chart_refresh_error",
                detail,
                config,
                root,
                stack: error?.stack || "",
              });
            });
        };
        window.addEventListener("mei:query-state-change", onQueryStateChange);
        root.__meiAnalyticsQueryStateCleanup = () => {
          window.removeEventListener("mei:query-state-change", onQueryStateChange);
        };
      }
      setDrilldownOverlayStatus(root, "ready");
      dispatchPreviewUpdated("drilldown");
      return true;
    } catch (error) {
      recordPopupDebugIssue({
        level: "error",
        message: String(error?.message || error || "分析型下钻看板渲染失败"),
        phase: "analytics_render_error",
        detail,
        config,
        root,
        stack: error?.stack || "",
      });
      setDrilldownOverlayStatus(root, "error");
      return false;
    }
  }



/* ===== spa-navigation/drilldown/swimlane-preview/p1.js ===== */
  function resolveListPreviewMapping(config) {
    const slot = config?.rowPreviewSlot || config?.previewSlot || {};
    const mapping = slot?.mapping;
    if (mapping && typeof mapping === "object" && !Array.isArray(mapping)) {
      return mapping;
    }
    return null;
  }

  function isSwimlanePreview(config) {
    const mapping = resolveListPreviewMapping(config);
    return (
      String(mapping?.preview_mode || mapping?.previewMode || "").trim() === "swimlane" &&
      Array.isArray(mapping?.lanes) &&
      mapping.lanes.length > 0
    );
  }

  function isCaseDetailCardPreview(config) {
    const mapping = resolveListPreviewMapping(config);
    const mode = String(mapping?.preview_mode || mapping?.previewMode || "").trim();
    return mode === "case_detail_card" || mode === "row_form";
  }

  function mappingWantsRowForm(mapping) {
    if (!mapping || typeof mapping !== "object") return false;
    const mode = String(mapping.preview_mode || mapping.previewMode || "").trim();
    return (
      mode === "row_form" ||
      mapping.auto_fields === true ||
      mapping.autoFields === true ||
      mapping.form_fields === "all" ||
      mapping.formFields === "all"
    );
  }

  function isTypicalCaseCardPreview(config) {
    const mapping = resolveListPreviewMapping(config);
    return String(mapping?.preview_mode || mapping?.previewMode || "").trim() === "typical_case_card";
  }

  function isDocumentPreview(config) {
    const mapping = resolveListPreviewMapping(config);
    return String(mapping?.preview_mode || mapping?.previewMode || "").trim() === "document_preview";
  }

  function isVideoSubtitleCockpitPreview(config) {
    const mapping = resolveListPreviewMapping(config);
    return (
      String(mapping?.preview_mode || mapping?.previewMode || "").trim() === "video_subtitle_cockpit"
    );
  }

  function isSheetDetailCardPreview(config) {
    return isCaseDetailCardPreview(config) || isTypicalCaseCardPreview(config);
  }

  function isPreviewOnlyMapping(config) {
    const mapping = resolveListPreviewMapping(config);
    if (!Boolean(mapping?.preview_only || mapping?.previewOnly)) return false;
    // 左清单 + 右预览：preview_only 只表示右侧是纯 PDF，不能把整板折成独立预览。
    if (String(config?.sceneLocalNav?.kind || config?.scene_local_nav?.kind || "").trim() === "list_preview_drilldown_page") {
      return false;
    }
    if (nonEmptyString(config?.rowPreviewSourceZoneId, config?.row_preview_source_zone_id)) {
      return false;
    }
    return true;
  }

  function resolveCaseDetailFieldValue(row, spec) {
    if (!row || typeof row !== "object" || !spec || typeof spec !== "object") return "";
    const primary = String(spec.field || spec.column || "").trim();
    const fallbacks = cloneArray(spec.fallback_fields || spec.fallbackFields)
      .map((entry) => String(entry || "").trim())
      .filter(Boolean);
    for (const key of [primary, ...fallbacks]) {
      if (!key) continue;
      const value = row[key];
      if (value != null && String(value).trim()) {
        return String(value).trim();
      }
    }
    return "";
  }

  function splitMechanismDocuments(text) {
    const raw = String(text || "").trim();
    if (!raw || raw === "—" || raw === "-" || raw === "无") return [];
    return raw
      .split(/[、,，;；]/)
      .map((entry) => entry.trim().replace(/^[《]+|[》]+$/g, "").trim())
      .filter(Boolean)
      .map((entry) => (entry.startsWith("《") ? entry : `《${entry}》`));
  }

  function applyExternalCaseDetailRowEnricher(row, detail) {
    if (!row || typeof row !== "object") {
      return row;
    }
    const enricher =
      typeof window !== "undefined" ? window.__meiCaseDetailRowEnricher : null;
    if (typeof enricher !== "function") {
      return row;
    }
    const enriched = enricher(row, detail);
    return enriched && typeof enriched === "object" ? enriched : row;
  }

  function enrichCaseDetailRow(row, detail) {
    if (!row || typeof row !== "object") return row;
    const enriched = { ...row };
    const filters =
      detail?.drilldown_filters && typeof detail.drilldown_filters === "object"
        ? detail.drilldown_filters
        : detail?.default_filters && typeof detail.default_filters === "object"
          ? detail.default_filters
          : {};
    const title = String(detail?.label ?? detail?.desc ?? "").trim();
    if (title && !String(enriched.title ?? enriched.label ?? "").trim()) {
      enriched.title = title;
    }
    Object.entries(filters).forEach(([key, value]) => {
      const text = String(value ?? "").trim();
      if (!text) return;
      enriched[key] = text;
      // Identity filters must win over a mismatched preview row (scalar-rowset often ignores them).
      if (key === "warningId" || key === "预警ID") {
        enriched.warningId = text;
        enriched["预警ID"] = text;
      }
      if (key === "resultId" || key === "处理结果ID") {
        enriched.resultId = text;
        enriched["处理结果ID"] = text;
      }
      if (key === "matterId" || key === "序号") {
        enriched.matterId = text;
        enriched["序号"] = text;
      }
      if (key === "matter" || key === "风险事项" || key === "监督事项") {
        enriched.matter = text;
        enriched["风险事项"] = text;
        enriched["监督事项"] = text;
      }
      if (key === "modelId" || key === "模型ID") {
        // Excel 浮点整型常变成 2025001.0 / number；详情卡统一成无小数文本。
        const normalized = (() => {
          if (typeof value === "number" && Number.isFinite(value) && Math.abs(value % 1) < Number.EPSILON) {
            return String(Math.trunc(value));
          }
          const raw = String(value ?? "").trim();
          return /^-?\d+\.0+$/.test(raw) ? raw.replace(/\.0+$/, "") : raw;
        })();
        if (!normalized) return;
        enriched.modelId = normalized;
        enriched["模型ID"] = normalized;
        return;
      }
      if (key === "mechanismName" || key === "机制名称" || key === "健全机制") {
        // 过滤值可能是顿号多值；只取首个可匹配的机制名称，避免整串无法命中 CSV 行。
        const parts = String(text || "")
          .split(/[、,，;；]/)
          .map((entry) =>
            String(entry || "")
              .trim()
              .replace(/^[《]+|[》]+$/g, "")
              .trim(),
          )
          .filter(Boolean);
        const normalized = parts[0] || String(text).replace(/^[《]+|[》]+$/g, "").trim();
        if (!normalized) return;
        enriched.mechanismName = normalized;
        enriched["机制名称"] = normalized;
        enriched["健全机制"] = normalized;
        return;
      }
    });
    deriveWarningHandlingStatusFlags(enriched);
    return applyExternalCaseDetailRowEnricher(enriched, detail);
  }

  function caseDetailFieldPresent(value) {
    const text = String(value ?? "").trim();
    return Boolean(text) && text !== "—" && text !== "-" && text !== "－";
  }

  /** 与 issue-handling 指标一致：跟踪ID+承办部门+办结时间 → 已办 / 在办 / 待办 */
  function deriveWarningHandlingStatusFlags(row) {
    if (!row || typeof row !== "object") return row;
    const hasExplicit =
      caseDetailFieldPresent(row["是否待办"]) ||
      caseDetailFieldPresent(row["是否在办"]) ||
      caseDetailFieldPresent(row["是否已办"]);
    if (hasExplicit) return row;
    const tracking = caseDetailFieldPresent(row["问题跟踪ID"]);
    const dept = caseDetailFieldPresent(row["承办部门"]);
    const closed = caseDetailFieldPresent(row["办结时间"]);
    let pending = "否";
    let inProgress = "否";
    let done = "否";
    if (tracking && dept && closed) {
      done = "是";
    } else if (tracking && dept) {
      inProgress = "是";
    } else {
      pending = "是";
    }
    row["是否待办"] = pending;
    row["是否在办"] = inProgress;
    row["是否已办"] = done;
    return row;
  }

  function caseCardObjectProps(config) {
    const nav =
      config?.sceneLocalNav && typeof config.sceneLocalNav === "object" ? config.sceneLocalNav : {};
    const locator =
      (nav.object_locator && typeof nav.object_locator === "object" && !Array.isArray(nav.object_locator)
        ? nav.object_locator
        : null) ||
      (nav.objectLocator && typeof nav.objectLocator === "object" && !Array.isArray(nav.objectLocator)
        ? nav.objectLocator
        : null) ||
      (config?.object_locator && typeof config.object_locator === "object" && !Array.isArray(config.object_locator)
        ? config.object_locator
        : null) ||
      (config?.objectLocator && typeof config.objectLocator === "object" && !Array.isArray(config.objectLocator)
        ? config.objectLocator
        : null);
    const objectType = nonEmptyString(
      locator?.object_type,
      locator?.objectType,
      nav.object_type,
      nav.objectType,
      config?.object_type,
      config?.objectType,
    );
    const identityField = nonEmptyString(
      locator?.identity_field,
      locator?.identityField,
      nav.identity_field,
      nav.identityField,
      config?.identity_field,
      config?.identityField,
    );
    const resolved =
      objectType || identityField
        ? {
            ...(locator && typeof locator === "object" ? locator : {}),
            ...(objectType ? { object_type: objectType, objectType } : {}),
            ...(identityField ? { identity_field: identityField, identityField } : {}),
          }
        : {
            object_type: "zhifa.Warning",
            objectType: "zhifa.Warning",
            identity_field: "预警ID",
            identityField: "预警ID",
          };
    return {
      object_locator: resolved,
      objectLocator: resolved,
    };
  }

  async function loadCaseCardDrilldownMeta() {
    if (typeof window !== "undefined" && window.MeiDrilldownMeta) {
      return window.MeiDrilldownMeta;
    }
    try {
      const mod = await import("/workspace-components/cockpit/drilldown-meta.js");
      const api = {
        resolveObjectFieldTargets: mod.resolveObjectFieldTargets,
        emitObjectFieldOpen: mod.emitObjectFieldOpen,
        resolveObjectFieldLinks: mod.resolveObjectFieldLinks,
        splitMultiObjectKeys: mod.splitMultiObjectKeys,
      };
      if (typeof window !== "undefined") {
        window.MeiDrilldownMeta = api;
      }
      return api;
    } catch (_error) {
      return null;
    }
  }

  function filterCaseCardObjectTargets(targets, spec) {
    const allowed = cloneArray(spec?.object_types || spec?.objectTypes)
      .map((type) => String(type || "").trim())
      .filter(Boolean);
    let list = Array.isArray(targets) ? targets : [];
    if (allowed.length) {
      list = list.filter((target) =>
        allowed.includes(String(target?.objectType || target?.object_type || "").trim()),
      );
    }
    if (window.MeiDrilldownMeta?.preferUniqueObjectTargets) {
      return window.MeiDrilldownMeta.preferUniqueObjectTargets(list, allowed);
    }
    return list;
  }

  function createCaseCardObjectLinkButton(text) {
    const link = document.createElement("button");
    link.type = "button";
    link.className = "access-drilldown-case-object-link";
    link.textContent = String(text ?? "");
    return link;
  }

  function bindCaseCardObjectOpen(el, host, row, field, spec, config) {
    if (!(el instanceof HTMLElement) || !field) return;
    el.classList.add("is-object-link");
    el.setAttribute("role", "button");
    el.tabIndex = 0;
    el.title = el.title || "打开智能对象";
    const open = async (event) => {
      event?.preventDefault?.();
      event?.stopPropagation?.();
      const meta = await loadCaseCardDrilldownMeta();
      if (!meta?.resolveObjectFieldTargets || !meta?.emitObjectFieldOpen) return;
      const fieldCandidates = [
        field,
        ...cloneArray(spec?.fallback_fields || spec?.fallbackFields),
      ]
        .map((entry) => String(entry || "").trim())
        .filter(Boolean);
      const uniqueFields = [...new Set(fieldCandidates)];
      let props = caseCardObjectProps(config);
      let targets = [];
      const tryResolve = (nextProps) => {
        for (const candidate of uniqueFields) {
          const resolved = filterCaseCardObjectTargets(
            meta.resolveObjectFieldTargets(nextProps, row, candidate),
            spec,
          );
          if (resolved.length) return resolved;
        }
        return [];
      };
      targets = tryResolve(props);
      // 典型案例等页缺 object_locator 时会回落到 Warning，关联预警ID/健全机制会空；按字段再试 IssueResult。
      if (!targets.length) {
        const retryTypes = ["zhifa.IssueResult", "zhifa.Warning", "zhifa.MechanismDocument"];
        for (const type of retryTypes) {
          const locator = {
            object_type: type,
            objectType: type,
            ...(type === "zhifa.IssueResult"
              ? { identity_field: "处理结果ID", identityField: "处理结果ID" }
              : type === "zhifa.MechanismDocument"
                ? { identity_field: "机制名称", identityField: "机制名称" }
                : { identity_field: "预警ID", identityField: "预警ID" }),
          };
          const retryProps = { object_locator: locator, objectLocator: locator };
          targets = tryResolve(retryProps);
          if (targets.length) {
            props = retryProps;
            break;
          }
        }
      }
      // 多值 ID 芯片：仅打开当前 chip 对应 identity
      const chipKey = String(el.dataset?.objectKey || "").trim();
      if (chipKey) {
        const normalizeKey = (raw) =>
          String(raw ?? "")
            .trim()
            .replace(/^[《]+|[》]+$/g, "")
            .trim();
        const chipNorm = normalizeKey(chipKey);
        const filtered = targets.filter((target) => {
          const key = String(target?.objectKey || target?.object_key || "").trim();
          return key === chipKey || normalizeKey(key) === chipNorm;
        });
        if (filtered.length) {
          targets = filtered;
        } else if (targets.length && chipNorm) {
          // 多值顿号拆分后仍对不上时：用当前 chip 身份覆盖模板 target（健全机制常见）
          const template = targets[0];
          targets = [
            {
              ...template,
              objectKey: chipNorm,
              object_key: chipNorm,
              label: chipNorm,
              filterKey: nonEmptyString(template?.filterKey, template?.filter_key, "mechanismName"),
              filter_key: nonEmptyString(template?.filterKey, template?.filter_key, "mechanismName"),
            },
          ];
        } else if (chipNorm && (field === "健全机制" || field === "机制名称")) {
          // 完全解析失败时仍尝试打开机制 PDF 详情
          const locator = {
            object_type: "zhifa.MechanismDocument",
            objectType: "zhifa.MechanismDocument",
            identity_field: "机制名称",
            identityField: "机制名称",
          };
          props = { object_locator: locator, objectLocator: locator };
          const links = meta.resolveObjectFieldLinks?.(props) || {};
          const specs = Array.isArray(links["机制名称"])
            ? links["机制名称"]
            : Array.isArray(links["健全机制"])
              ? links["健全机制"]
              : [];
          const spec0 = specs[0] || {};
          const openPopup =
            (spec0.openPopup && typeof spec0.openPopup === "object" ? spec0.openPopup : null) ||
            (spec0.open_popup && typeof spec0.open_popup === "object" ? spec0.open_popup : null) ||
            {
              kind: "scene_open",
              mode: "popup",
              type: "popup",
              projection: "overlay",
              overlay_size: "large",
              scene_id: "mechanism_document_detail_page",
              scene_file:
                "src/scene/home/t1/region-right-rail/section-effect/plane-mechanism-document-detail.mei",
              page_scene_id: "mechanism_document_detail_page",
              page_scene_file:
                "src/scene/home/t1/region-right-rail/section-effect/plane-mechanism-document-detail.mei",
              params: {
                metric: {
                  __ref: "metric_ref",
                  __args: {
                    arg0: "mechanism_document_detail",
                    bundle: "metrics/effectiveness.bundle.mei",
                  },
                },
                rowset_dataset_id: "mechanism_documents",
              },
            };
          targets = [
            {
              role: "relation",
              objectType: "zhifa.MechanismDocument",
              objectKey: chipNorm,
              keyMode: "identity",
              filterKey: "mechanismName",
              filter_key: "mechanismName",
              hasDetail: true,
              openPopup,
              detailPage:
                spec0.detailPage ||
                spec0.detail_page ||
                "zhifa/home/t1/region-right-rail/section-effect/plane-mechanism-document-detail",
              label: chipNorm,
            },
          ];
        } else {
          targets = [];
        }
      }
      if (!targets.length) return;
      const emitHost = host instanceof HTMLElement ? host : el;
      if (targets.length === 1) {
        meta.emitObjectFieldOpen(emitHost, targets[0], row, props);
        return;
      }
      openCaseCardObjectChooser(el, targets, (target) => {
        meta.emitObjectFieldOpen(emitHost, target, row, props);
      }, field);
    };
    el.addEventListener("click", open);
    el.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") open(event);
    });
  }

  function openCaseCardObjectChooser(anchor, targets, onPick, fieldLabel = "") {
    const existing = document.querySelector(".access-drilldown-object-chooser");
    if (existing) existing.remove();
    const menu = document.createElement("div");
    menu.className = "access-drilldown-object-chooser";
    menu.setAttribute("role", "menu");
    const title = document.createElement("div");
    title.className = "access-drilldown-object-chooser-title";
    const fieldName = String(fieldLabel || "").trim();
    title.textContent = fieldName ? `选择${fieldName}` : "选择智能对象";
    menu.appendChild(title);
    targets.forEach((target) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "access-drilldown-object-chooser-item";
      button.setAttribute("role", "menuitem");
      button.textContent = String(
        target?.label || target?.objectKey || target?.object_key || "",
      ).trim();
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        menu.remove();
        onPick?.(target);
      });
      menu.appendChild(button);
    });
    document.body.appendChild(menu);
    const rect = anchor.getBoundingClientRect();
    menu.style.position = "fixed";
    menu.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - 260))}px`;
    menu.style.top = `${Math.min(rect.bottom + 4, window.innerHeight - 8)}px`;
    const close = (event) => {
      if (menu.contains(event.target) || anchor.contains?.(event.target)) return;
      menu.remove();
      document.removeEventListener("mousedown", close, true);
    };
    setTimeout(() => document.addEventListener("mousedown", close, true), 0);
  }

  function mappingShowsHeader(mapping) {
    return mapping?.show_header !== false && mapping?.showHeader !== false;
  }

  function mappingShowsSummary(mapping) {
    return mapping?.show_summary !== false && mapping?.showSummary !== false;
  }

  function mappingShowsMeta(mapping) {
    return mapping?.show_meta !== false && mapping?.showMeta !== false;
  }

  function mappingHasTypicalCaseStats(mapping) {
    return (
      cloneArray(mapping?.tags).length > 0 ||
      cloneArray(mapping?.facts).length > 0 ||
      cloneArray(mapping?.status_flags || mapping?.statusFlags).length > 0 ||
      cloneArray(mapping?.metrics).length > 0
    );
  }

  function resolveCaseDetailSituationText(row, mapping) {
    const situationField = String(mapping?.situation_field || mapping?.situationField || "").trim();
    if (situationField) {
      const value = resolveCaseDetailFieldValue(row, {
        field: situationField,
        fallback_fields: mapping?.situation_fallback_fields || mapping?.situationFallbackFields,
      });
      if (value) return value;
    }
    return resolveCaseDetailFieldValue(row, {
      field: String(mapping?.summary_field || mapping?.summaryField || "基本情况").trim(),
      fallback_fields: mapping?.summary_fallback_fields || mapping?.summaryFallbackFields,
    });
  }

  function appendCaseDetailMetaItem(parent, label, value) {
    const item = document.createElement("div");
    item.className = "access-drilldown-case-detail-meta-item";
    const labelEl = document.createElement("span");
    labelEl.className = "access-drilldown-case-detail-meta-label";
    labelEl.textContent = `${label}：`;
    const valueEl = document.createElement("span");
    valueEl.className = "access-drilldown-case-detail-meta-value";
    valueEl.textContent = value || "—";
    item.appendChild(labelEl);
    item.appendChild(valueEl);
    parent.appendChild(item);
  }

  function appendCaseDetailMetaRow(panel, row, mapping) {
    const specs = [
      ...cloneArray(mapping?.meta_left || mapping?.metaLeft),
      ...cloneArray(mapping?.meta_right || mapping?.metaRight),
    ];
    if (!specs.length) return;
    const meta = document.createElement("div");
    meta.className = "access-drilldown-case-detail-meta";
    specs.forEach((spec) => {
      const label = String(spec?.label || spec?.field || "").trim();
      if (!label) return;
      appendCaseDetailMetaItem(meta, label, resolveCaseDetailFieldValue(row, spec));
    });
    if (meta.childElementCount) panel.appendChild(meta);
  }

  /** 与明细表一致：风险等级三色块 / 预警等级单色块 */
  function appendWarningLevelBlocks(valueEl, fieldName, rawValue) {
    const colors = {
      红: "var(--mei-color-warning_level_red, #E53935)",
      黄: "var(--mei-color-warning_level_yellow, #FFB300)",
      蓝: "var(--mei-color-warning_level_blue, #1E88E5)",
      灰: "var(--mei-color-warning_level_grey, #90A4AE)",
    };
    const order = ["红", "黄", "蓝"];
    const text = String(rawValue ?? "").trim();
    const active = new Set(order.filter((key) => text.includes(key)));
    const multi = fieldName === "风险等级";
    const root = document.createElement("span");
    root.className = `mei-warning-level-blocks ${multi ? "is-multi" : "is-single"}`;
    root.title = text;
    if (multi) {
      order.forEach((key) => {
        const on = active.has(key);
        const item = document.createElement("span");
        item.className = `mei-warning-level-item${on ? " is-on" : " is-off"}`;
        item.style.background = on ? colors[key] : "transparent";
        item.style.borderColor = on ? colors[key] : colors.灰;
        const label = document.createElement("span");
        label.className = "mei-warning-level-label";
        label.textContent = key;
        item.appendChild(label);
        root.appendChild(item);
      });
    } else {
      const top = order.find((key) => active.has(key)) || "";
      const on = Boolean(top);
      const item = document.createElement("span");
      item.className = `mei-warning-level-item${on ? " is-on" : " is-off"}`;
      item.style.background = on ? colors[top] : "transparent";
      item.style.borderColor = on ? colors[top] : colors.灰;
      const label = document.createElement("span");
      label.className = "mei-warning-level-label";
      label.textContent = on ? top : "";
      item.appendChild(label);
      root.appendChild(item);
    }
    valueEl.appendChild(root);
  }

  function mappingAllowsAutoFields(mapping) {
    if (!mapping || typeof mapping !== "object") return true;
    // 定制卡可显式关闭：仅展示 field_order。
    if (mapping.auto_fields === false || mapping.autoFields === false) return false;
    return true;
  }

  function isLongRowFormField(name, value) {
    if (value.length >= 28) return true;
    return /依据|规则|描述|问题|表现|政策|数据|情况|说明|附件/.test(String(name || ""));
  }

  /** 表单风格：按 field_order 展开行字段；排除注入噪音键，避免英文 title/matter 污染。 */
  function appendRowFormFields(panel, row, mapping) {
    if (!row || typeof row !== "object" || Array.isArray(row)) return;
    const exclude = new Set(
      [
        "title",
        "label",
        "matter",
        "matterId",
        "监督事项",
        "warningId",
        "resultId",
        "modelId",
        ...cloneArray(mapping?.exclude_fields || mapping?.excludeFields),
      ]
        .map((name) => String(name || "").trim())
        .filter(Boolean),
    );
    const preferred = cloneArray(mapping?.field_order || mapping?.fieldOrder)
      .map((name) => String(name || "").trim())
      .filter(Boolean);
    const labelMap =
      mapping?.field_labels && typeof mapping.field_labels === "object"
        ? mapping.field_labels
        : mapping?.fieldLabels && typeof mapping.fieldLabels === "object"
          ? mapping.fieldLabels
          : {};
    const seen = new Set();
    const keys = [];
    preferred.forEach((key) => {
      if (!Object.prototype.hasOwnProperty.call(row, key) || seen.has(key)) return;
      seen.add(key);
      keys.push(key);
    });
    // 通用默认：无 field_order → 全字段；有 field_order 且 auto_fields≠false → 顺序优先后补齐。
    // 定制卡：auto_fields=false + field_order → 仅展示指定列。
    if (!preferred.length || mappingAllowsAutoFields(mapping)) {
      Object.keys(row).forEach((key) => {
        if (seen.has(key)) return;
        seen.add(key);
        keys.push(key);
      });
    }
    const form = document.createElement("div");
    form.className = "access-drilldown-row-form";
    form.setAttribute("role", "list");
    keys.forEach((key) => {
      const name = String(key || "").trim();
      if (!name || name.startsWith("__") || exclude.has(name)) return;
      // 过滤英文/内部别名，行级详情只展示业务中文列。
      if (/^[A-Za-z][A-Za-z0-9_]*$/.test(name)) return;
      const raw = row[name];
      if (raw != null && typeof raw === "object") return;
      let value = String(raw ?? "").trim();
      // 模型/预警等 ID：去掉 Excel 浮点旁路留下的 ".0"
      if ((name.endsWith("ID") || name.endsWith("Id") || name === "序号") && /^-?\d+\.0+$/.test(value)) {
        value = value.replace(/\.0+$/, "");
      } else if (typeof raw === "number" && Number.isFinite(raw) && Math.abs(raw % 1) < Number.EPSILON) {
        value = String(Math.trunc(raw));
      }
      const item = document.createElement("div");
      item.className = "access-drilldown-row-form-item";
      item.setAttribute("role", "listitem");
      if (isLongRowFormField(name, value)) {
        item.classList.add("access-drilldown-row-form-item--long");
      }
      const labelEl = document.createElement("div");
      labelEl.className = "access-drilldown-row-form-label";
      labelEl.textContent = String(labelMap[name] || name).trim() || name;
      const valueEl = document.createElement("div");
      valueEl.className = "access-drilldown-row-form-value";
      if (name === "风险等级" || name === "预警等级") {
        valueEl.classList.add("access-drilldown-row-form-value--level");
        appendWarningLevelBlocks(valueEl, name, value);
      } else {
        valueEl.textContent = value || "—";
      }
      item.appendChild(labelEl);
      item.appendChild(valueEl);
      form.appendChild(item);
    });
    if (form.childElementCount) panel.appendChild(form);
  }

  function appendCaseDetailSection(block, section, row, mapping, config = null) {
    const label = String(section?.label || "").trim();
    const kind = String(section?.kind || "").trim();
    const field = String(section?.field || "").trim();
    const hideLabel = section?.hide_label === true || section?.hideLabel === true;
    let value = resolveCaseDetailFieldValue(row, section);
    if (kind === "situation") {
      value = resolveCaseDetailSituationText(row, mapping);
    }
    if (!label && !hideLabel && kind !== "situation" && !field) return;
    const sectionEl = document.createElement("div");
    sectionEl.className = "access-drilldown-case-detail-section";
    if (kind === "id") {
      const idRow = document.createElement("div");
      idRow.className = "access-drilldown-case-detail-id-row";
      const idLabel = document.createElement("span");
      idLabel.className = "access-drilldown-case-detail-id-label";
      idLabel.textContent = label;
      idRow.appendChild(idLabel);
      const rawKeys = (() => {
        if (window.MeiDrilldownMeta?.splitMultiObjectKeys) {
          return window.MeiDrilldownMeta.splitMultiObjectKeys(value);
        }
        return String(value ?? "")
          .split(/[\n\r\s]+/)
          .map((part) => String(part || "").trim().replace(/^\d+\.\s*/, ""))
          .filter(Boolean);
      })();
      const keys = rawKeys.length ? rawKeys : value ? [String(value).trim()] : [];
      if (!keys.length) {
        const empty = document.createElement("span");
        empty.className = "access-drilldown-case-detail-id-chip";
        empty.textContent = "—";
        idRow.appendChild(empty);
      } else {
        const wantsLink = section?.object_link === true || section?.objectLink === true;
        keys.forEach((key) => {
          if (wantsLink && field) {
            const idValue = createCaseCardObjectLinkButton(key);
            idValue.dataset.objectKey = key;
            bindCaseCardObjectOpen(idValue, block, row, field, section, config);
            idRow.appendChild(idValue);
            return;
          }
          const idValue = document.createElement("span");
          idValue.className = "access-drilldown-case-detail-id-chip";
          idValue.textContent = key;
          idRow.appendChild(idValue);
        });
      }
      sectionEl.appendChild(idRow);
      block.appendChild(sectionEl);
      return;
    }
    if (label && !hideLabel) {
      const labelEl = document.createElement("div");
      labelEl.className = "access-drilldown-case-detail-section-label";
      labelEl.textContent = label;
      sectionEl.appendChild(labelEl);
    }
    const body = document.createElement("div");
    body.className = "access-drilldown-case-detail-section-body";
    if ((label === "健全机制" || label === "制度文件" || field === "健全机制") && value) {
      const list = document.createElement("ul");
      list.className = "access-drilldown-case-detail-mechanism-list";
      const wantsLink = section?.object_link === true || section?.objectLink === true;
      splitMechanismDocuments(value).forEach((doc) => {
        const li = document.createElement("li");
        if (wantsLink && field) {
          const link = createCaseCardObjectLinkButton(doc);
          // 机制名称 identity 通常不含书名号；展示可带《》，匹配时剥离
          link.dataset.objectKey = String(doc || "")
            .trim()
            .replace(/^[《]+|[》]+$/g, "")
            .trim();
          bindCaseCardObjectOpen(link, block, row, field, section, config);
          li.appendChild(link);
        } else {
          li.textContent = doc;
        }
        list.appendChild(li);
      });
      if (!list.childElementCount) {
        body.textContent = value;
      } else {
        body.appendChild(list);
      }
    } else {
      body.textContent = value || "—";
    }
    sectionEl.appendChild(body);
    block.appendChild(sectionEl);
  }

  function resolveCaseDetailHeaderSubtitle(row, detail) {
    return nonEmptyString(
      detail?.value,
      resolveCaseDetailFieldValue(row, { field: "处理结果ID" }),
      resolveCaseDetailFieldValue(row, { field: "预警ID" }),
    );
  }

  function appendCaseDetailHeader(panel, row, mapping, detail = null) {
    const badge = String(mapping?.card_badge || mapping?.cardBadge || "典型案例").trim();
    const title = resolveCaseDetailFieldValue(row, {
      field: String(mapping?.title_field || mapping?.titleField || "案例名称").trim(),
      fallback_fields: mapping?.title_fallback_fields || mapping?.titleFallbackFields,
    });
    const header = document.createElement("div");
    header.className = "access-drilldown-case-detail-header";
    const main = document.createElement("div");
    main.className = "access-drilldown-case-detail-header-main";
    const badgeEl = document.createElement("div");
    badgeEl.className = "access-drilldown-case-detail-badge";
    badgeEl.textContent = badge;
    main.appendChild(badgeEl);
    const titleEl = document.createElement("h2");
    titleEl.className = "access-drilldown-case-detail-title";
    titleEl.textContent = title || "典型案例详情";
    main.appendChild(titleEl);
    const subtitleId = resolveCaseDetailHeaderSubtitle(row, detail);
    // 标题已是身份 ID 时不再重复副标题
    if (subtitleId && subtitleId !== title) {
      const sub = document.createElement("span");
      sub.className = "access-drilldown-case-detail-subtitle";
      sub.textContent = subtitleId;
      main.appendChild(sub);
    }
    header.appendChild(main);
    panel.appendChild(header);
  }

  function resolveWarningLevelTone(value) {
    const text = String(value ?? "").trim();
    if (text.includes("红")) return "red";
    if (text.includes("黄")) return "yellow";
    if (text.includes("蓝")) return "blue";
    return "default";
  }

  function formatTypicalCaseMetricValue(row, spec) {
    const raw = resolveCaseDetailFieldValue(row, spec);
    if (!raw) return "—";
    const numeric = Number(raw.replace(/,/g, ""));
    const unit = String(spec?.unit || "").trim();
    if (Number.isFinite(numeric)) {
      const formatted = Number.isInteger(numeric) ? String(numeric) : numeric.toFixed(2).replace(/\.?0+$/, "");
      return unit ? `${formatted}${unit}` : formatted;
    }
    return unit ? `${raw}${unit}` : raw;
  }

  function appendTypicalCaseTagRow(panel, row, mapping, config = null) {
    const tags = cloneArray(mapping?.tags);
    if (!tags.length) return;
    const tagRow = document.createElement("div");
    tagRow.className = "access-drilldown-typical-case-tags";
    tags.forEach((spec) => {
      const label = String(spec?.label || spec?.field || "").trim();
      const field = String(spec?.field || "").trim();
      if (!label || !field) return;
      const value = resolveCaseDetailFieldValue(row, spec);
      if (!value) return;
      const tag = document.createElement("span");
      const kind = String(spec?.kind || "").trim();
      if (kind === "warning_level") {
        tag.className =
          "access-drilldown-typical-case-tag access-drilldown-typical-case-tag--warning-level";
        const labelEl = document.createElement("span");
        labelEl.className = "access-drilldown-typical-case-tag-label";
        labelEl.textContent = `${label}：`;
        tag.appendChild(labelEl);
        appendWarningLevelBlocks(tag, field, value);
      } else if (spec?.object_link === true || spec?.objectLink === true) {
        // 与明细表 cell-object-link 一致：标签普通文本 + accent 下划线值链接
        tag.className =
          "access-drilldown-typical-case-tag access-drilldown-typical-case-tag--with-object-link";
        const labelEl = document.createElement("span");
        labelEl.className = "access-drilldown-typical-case-tag-label";
        labelEl.textContent = `${label}：`;
        const link = createCaseCardObjectLinkButton(value);
        bindCaseCardObjectOpen(link, panel, row, field, spec, config);
        tag.appendChild(labelEl);
        tag.appendChild(link);
      } else {
        tag.className = "access-drilldown-typical-case-tag";
        tag.textContent = `${label}：${value}`;
      }
      tagRow.appendChild(tag);
    });
    if (tagRow.childElementCount) panel.appendChild(tagRow);
  }

  function closeCaseCardFactPopover() {
    const existing = document.querySelector(".access-drilldown-case-fact-popover");
    if (existing) existing.remove();
    if (typeof window.__meiCaseFactPopoverCleanup === "function") {
      window.__meiCaseFactPopoverCleanup();
      window.__meiCaseFactPopoverCleanup = null;
    }
  }

  function openCaseCardFactPopover(anchor, fullText, title) {
    closeCaseCardFactPopover();
    const pop = document.createElement("div");
    pop.className = "access-drilldown-case-fact-popover";
    pop.setAttribute("role", "dialog");
    pop.setAttribute("aria-label", title || "详细内容");
    const head = document.createElement("div");
    head.className = "access-drilldown-case-fact-popover-head";
    const titleEl = document.createElement("div");
    titleEl.className = "access-drilldown-case-fact-popover-title";
    titleEl.textContent = title || "详细内容";
    const closeBtn = document.createElement("button");
    closeBtn.type = "button";
    closeBtn.className = "access-drilldown-case-fact-popover-close";
    closeBtn.setAttribute("aria-label", "关闭");
    closeBtn.textContent = "×";
    closeBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      closeCaseCardFactPopover();
    });
    head.appendChild(titleEl);
    head.appendChild(closeBtn);
    const body = document.createElement("div");
    body.className = "access-drilldown-case-fact-popover-body";
    body.textContent = fullText;
    pop.appendChild(head);
    pop.appendChild(body);
    document.body.appendChild(pop);
    const rect = anchor.getBoundingClientRect();
    const width = Math.min(420, Math.max(280, window.innerWidth - 24));
    pop.style.position = "fixed";
    pop.style.width = `${width}px`;
    pop.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - width - 8))}px`;
    pop.style.top = `${Math.min(rect.bottom + 6, window.innerHeight - 12)}px`;
    const onDoc = (event) => {
      if (pop.contains(event.target) || anchor.contains?.(event.target)) return;
      closeCaseCardFactPopover();
    };
    const onKey = (event) => {
      if (event.key === "Escape") closeCaseCardFactPopover();
    };
    setTimeout(() => {
      document.addEventListener("mousedown", onDoc, true);
      document.addEventListener("keydown", onKey, true);
    }, 0);
    window.__meiCaseFactPopoverCleanup = () => {
      document.removeEventListener("mousedown", onDoc, true);
      document.removeEventListener("keydown", onKey, true);
    };
  }

  function appendTypicalCaseFacts(panel, row, mapping) {
    const facts = cloneArray(mapping?.facts);
    if (!facts.length) return;
    const factsRoot = document.createElement("div");
    factsRoot.className = "access-drilldown-typical-case-facts";
    const maxChars = Math.max(
      8,
      Number(mapping?.fact_truncate_chars || mapping?.factTruncateChars || 16) || 16,
    );
    facts.forEach((spec) => {
      const label = String(spec?.label || spec?.field || "").trim();
      if (!label) return;
      const full = resolveCaseDetailFieldValue(row, spec) || "—";
      const item = document.createElement("div");
      item.className = "access-drilldown-typical-case-fact";
      const labelEl = document.createElement("div");
      labelEl.className = "access-drilldown-typical-case-fact-label";
      labelEl.textContent = label;
      const valueEl = document.createElement("div");
      valueEl.className = "access-drilldown-typical-case-fact-value";
      const chars = [...full];
      const needsTruncate = full !== "—" && chars.length > maxChars;
      const bindFullText = (anchor) => {
        const open = (event) => {
          event?.preventDefault?.();
          event?.stopPropagation?.();
          openCaseCardFactPopover(anchor, full, label);
        };
        anchor.addEventListener("click", open);
        anchor.addEventListener("keydown", (event) => {
          if (event.key === "Enter" || event.key === " ") open(event);
        });
      };
      if (needsTruncate) {
        valueEl.classList.add("is-truncated");
        valueEl.textContent = `${chars.slice(0, maxChars).join("")}…`;
        valueEl.title = "点击查看全文";
        valueEl.setAttribute("role", "button");
        valueEl.tabIndex = 0;
        bindFullText(valueEl);
        const more = document.createElement("button");
        more.type = "button";
        more.className = "access-drilldown-case-fact-more";
        more.textContent = "查看全文";
        more.title = "查看全文";
        bindFullText(more);
        item.appendChild(labelEl);
        item.appendChild(valueEl);
        item.appendChild(more);
      } else {
        valueEl.textContent = full;
        item.appendChild(labelEl);
        item.appendChild(valueEl);
        // 窄列 CSS 省略时补「查看全文」
        requestAnimationFrame(() => {
          if (!(valueEl.scrollWidth > valueEl.clientWidth + 1 || valueEl.scrollHeight > valueEl.clientHeight + 1)) {
            return;
          }
          if (item.querySelector(".access-drilldown-case-fact-more")) return;
          valueEl.classList.add("is-truncated");
          valueEl.title = "点击查看全文";
          valueEl.setAttribute("role", "button");
          valueEl.tabIndex = 0;
          bindFullText(valueEl);
          const more = document.createElement("button");
          more.type = "button";
          more.className = "access-drilldown-case-fact-more";
          more.textContent = "查看全文";
          more.title = "查看全文";
          bindFullText(more);
          item.appendChild(more);
        });
      }
      factsRoot.appendChild(item);
    });
    if (factsRoot.childElementCount) panel.appendChild(factsRoot);
  }

  function resolveVerifiedStatusPill(row, spec) {
    const field = String(spec?.field || "是否查实").trim();
    const raw = String(row?.[field] ?? "").trim();
    if (!raw || raw === "—" || raw === "-" || raw === "－") {
      return null;
    }
    const countField = String(spec?.count_field || spec?.countField || "查实条数").trim();
    const countRaw = String(row?.[countField] ?? "").trim();
    const countNum = Number(String(countRaw).replace(/,/g, ""));
    const countText =
      Number.isFinite(countNum) && countNum > 0
        ? String(Math.trunc(countNum))
        : countRaw && countRaw !== "—"
          ? countRaw
          : "";
    if (raw === "否" || raw === "0" || raw.includes("否")) {
      return { label: "未查实", active: false };
    }
    if (raw.includes("是") || (Number.isFinite(countNum) && countNum > 0)) {
      return { label: countText ? `查实${countText}条` : "查实", active: true };
    }
    return null;
  }

  function appendTypicalCaseStatusRow(panel, row, mapping, config = null) {
    const flags = cloneArray(mapping?.status_flags || mapping?.statusFlags);
    if (!flags.length) return;
    const statusRoot = document.createElement("div");
    statusRoot.className = "access-drilldown-typical-case-status";
    const title = document.createElement("div");
    title.className = "access-drilldown-typical-case-status-title";
    title.textContent = "办理状态";
    statusRoot.appendChild(title);
    const pills = document.createElement("div");
    pills.className = "access-drilldown-typical-case-status-pills";
    flags.forEach((spec) => {
      const kind = String(spec?.kind || "").trim();
      if (kind === "id_chip" || kind === "id") {
        const label = String(spec?.label || spec?.field || "").trim();
        const field = String(spec?.field || "").trim();
        if (!label || !field) return;
        const value = resolveCaseDetailFieldValue(row, spec);
        const rawKeys = (() => {
          if (window.MeiDrilldownMeta?.splitMultiObjectKeys) {
            return window.MeiDrilldownMeta.splitMultiObjectKeys(value);
          }
          return String(value ?? "")
            .split(/[\n\r\s]+/)
            .map((part) => String(part || "").trim().replace(/^\d+\.\s*/, ""))
            .filter(Boolean);
        })();
        const keys = rawKeys.length ? rawKeys : value ? [String(value).trim()] : [];
        if (!keys.length) return;
        const wantsLink = spec?.object_link === true || spec?.objectLink === true;
        keys.forEach((key) => {
          if (wantsLink) {
            // 可点 ID（如办理结果ID）：只展示 ID 值，与明细表 object-link 一致，不重复字段标签。
            const link = createCaseCardObjectLinkButton(key);
            link.dataset.objectKey = key;
            bindCaseCardObjectOpen(link, panel, row, field, spec, config);
            pills.appendChild(link);
            return;
          }
          const pill = document.createElement("span");
          pill.className =
            "access-drilldown-typical-case-status-pill access-drilldown-typical-case-status-pill--id";
          pill.textContent = `${label} ${key}`;
          pills.appendChild(pill);
        });
        return;
      }
      if (kind === "verified_count" || kind === "verified") {
        const resolved = resolveVerifiedStatusPill(row, spec);
        if (!resolved) return;
        const pill = document.createElement("span");
        pill.className = `access-drilldown-typical-case-status-pill${
          resolved.active ? " access-drilldown-typical-case-status-pill--on" : ""
        }`;
        pill.textContent = resolved.label;
        pills.appendChild(pill);
        return;
      }
      const label = String(spec?.label || spec?.field || "").trim();


/* ===== spa-navigation/drilldown/swimlane-preview/p2.js ===== */
      const field = String(spec?.field || "").trim();
      if (!label || !field) return;
      const active = isTruthyFlag(row?.[field]);
      const pill = document.createElement("span");
      pill.className = `access-drilldown-typical-case-status-pill${active ? " access-drilldown-typical-case-status-pill--on" : ""}`;
      pill.textContent = label;
      pills.appendChild(pill);
    });
    statusRoot.appendChild(pills);
    panel.appendChild(statusRoot);
  }

  function appendTypicalCaseMetricsRow(panel, row, mapping) {
    const metrics = cloneArray(mapping?.metrics);
    if (!metrics.length) return;
    const metricsRoot = document.createElement("div");
    metricsRoot.className = "access-drilldown-typical-case-metrics";
    const maxChars = Math.max(
      12,
      Number(mapping?.fact_truncate_chars || mapping?.factTruncateChars || 28) || 28,
    );
    metrics.forEach((spec) => {
      const label = String(spec?.label || spec?.field || "").trim();
      if (!label) return;
      const kind = String(spec?.kind || "").trim();
      const isText = kind === "text" || kind === "fact";
      const card = document.createElement("div");
      card.className = isText
        ? "access-drilldown-typical-case-metric access-drilldown-typical-case-metric--text"
        : "access-drilldown-typical-case-metric";
      const labelEl = document.createElement("div");
      labelEl.className = "access-drilldown-typical-case-metric-label";
      labelEl.textContent = label;
      const valueEl = document.createElement("div");
      valueEl.className = "access-drilldown-typical-case-metric-value";
      if (isText) {
        const full = resolveCaseDetailFieldValue(row, spec) || "—";
        const chars = [...full];
        const needsTruncate = full !== "—" && chars.length > maxChars;
        if (needsTruncate) {
          valueEl.classList.add("is-truncated");
          valueEl.textContent = `${chars.slice(0, maxChars).join("")}…`;
          valueEl.title = "点击查看全文";
          valueEl.setAttribute("role", "button");
          valueEl.tabIndex = 0;
          const open = (event) => {
            event?.preventDefault?.();
            event?.stopPropagation?.();
            openCaseCardFactPopover(valueEl, full, label);
          };
          valueEl.addEventListener("click", open);
          valueEl.addEventListener("keydown", (event) => {
            if (event.key === "Enter" || event.key === " ") open(event);
          });
        } else {
          valueEl.textContent = full;
        }
      } else {
        valueEl.textContent = formatTypicalCaseMetricValue(row, spec);
      }
      card.appendChild(labelEl);
      card.appendChild(valueEl);
      metricsRoot.appendChild(card);
    });
    if (metricsRoot.childElementCount) {
      metricsRoot.style.setProperty(
        "--case-metric-count",
        String(metricsRoot.childElementCount),
      );
      panel.appendChild(metricsRoot);
    }
  }

  function applyCaseDetailWarningTone(panel, row) {
    if (!(panel instanceof HTMLElement)) return;
    const tone = resolveWarningLevelTone(
      resolveCaseDetailFieldValue(row, { field: "预警等级" }),
    );
    if (tone !== "default") {
      panel.dataset.warningLevel = tone;
    } else {
      panel.removeAttribute("data-warning-level");
    }
  }

  function appendTypicalCaseStatsSection(panel, row, mapping, { wrapBand = false, config = null, factsOutsideBand = false } = {}) {
    if (!mappingHasTypicalCaseStats(mapping)) return;
    const bandTarget = (() => {
      if (!wrapBand) return panel;
      const band = document.createElement("div");
      band.className = "access-drilldown-case-detail-stats-band";
      const hideBandLabel =
        mapping?.hide_stats_band_label === true || mapping?.hideStatsBandLabel === true;
      if (hideBandLabel) {
        band.dataset.statsBandLabelHidden = "true";
      } else {
        const bandLabel = String(
          mapping?.stats_band_label ||
            mapping?.statsBandLabel ||
            mapping?.card_badge ||
            mapping?.cardBadge ||
            "实时预警",
        ).trim();
        if (bandLabel) band.dataset.statsBandLabel = bandLabel;
      }
      panel.appendChild(band);
      return band;
    })();
    appendTypicalCaseTagRow(bandTarget, row, mapping, config);
    if (!factsOutsideBand) {
      appendTypicalCaseFacts(bandTarget, row, mapping);
    }
    appendTypicalCaseStatusRow(bandTarget, row, mapping, config);
    appendTypicalCaseMetricsRow(bandTarget, row, mapping);
    if (factsOutsideBand) {
      appendTypicalCaseFacts(panel, row, mapping);
    }
  }

  function renderSheetDetailCardPanel(host, row, config, detail) {
    if (isTypicalCaseCardPreview(config)) {
      renderTypicalCaseCardPanel(host, row, config, detail);
      return;
    }
    renderCaseDetailCardPanel(host, row, config, detail);
  }

  function renderTypicalCaseCardPanel(host, row, config, detail) {
    if (!(host instanceof HTMLElement)) return;
    host.replaceChildren();
    host.classList.remove("access-drilldown-case-detail-host");
    host.classList.add("access-drilldown-typical-case-host");
    if (!row || typeof row !== "object") {
      const empty = document.createElement("div");
      empty.className = "access-drilldown-list-preview-empty";
      empty.textContent = "正在加载典型案例…";
      host.appendChild(empty);
      return;
    }
    const mapping = resolveListPreviewMapping(config);
    if (!mapping) {
      renderListPreviewItemPanel(host, row, config);
      return;
    }
    const enrichedRow = enrichCaseDetailRow(row, detail);
    const panel = document.createElement("div");
    panel.className = "access-drilldown-typical-case-panel";
    applyCaseDetailWarningTone(panel, enrichedRow);
    if (mappingShowsHeader(mapping)) {
      appendCaseDetailHeader(panel, enrichedRow, mapping, detail);
    }
    if (mappingShowsSummary(mapping)) {
      const summary = resolveCaseDetailFieldValue(enrichedRow, {
        field: String(mapping?.summary_field || mapping?.summaryField || "基本情况").trim(),
        fallback_fields: mapping?.summary_fallback_fields || mapping?.summaryFallbackFields,
      });
      const summaryBlock = document.createElement("div");
      summaryBlock.className = "access-drilldown-typical-case-summary";
      const summaryLabel = document.createElement("div");
      summaryLabel.className = "access-drilldown-typical-case-summary-label";
      summaryLabel.textContent = String(mapping?.summary_label || mapping?.summaryLabel || "基本情况").trim();
      const summaryText = document.createElement("div");
      summaryText.className = "access-drilldown-typical-case-summary-text";
      summaryText.textContent = summary || "—";
      summaryBlock.appendChild(summaryLabel);
      summaryBlock.appendChild(summaryText);
      panel.appendChild(summaryBlock);
    }
    appendTypicalCaseStatsSection(panel, enrichedRow, mapping, { config });
    host.appendChild(panel);
  }

  function renderCaseDetailCardPanel(host, row, config, detail) {
    if (!(host instanceof HTMLElement)) return;
    host.replaceChildren();
    host.classList.remove("access-drilldown-typical-case-host");
    host.classList.add("access-drilldown-case-detail-host");
    if (!row || typeof row !== "object") {
      const empty = document.createElement("div");
      empty.className = "access-drilldown-list-preview-empty";
      empty.textContent = "正在加载案例详情…";
      host.appendChild(empty);
      return;
    }
    const mapping = resolveListPreviewMapping(config);
    if (!mapping) {
      renderListPreviewItemPanel(host, row, config);
      return;
    }
    const enrichedRow = enrichCaseDetailRow(row, detail);
    const panel = document.createElement("div");
    panel.className = "access-drilldown-case-detail-panel";
    const previewMode = String(mapping?.preview_mode || mapping?.previewMode || "").trim();
    // 纯行级表单：跳过案例卡头/统计带/meta，只渲染 label-value 表单。
    if (previewMode === "row_form") {
      host.classList.remove("access-drilldown-case-detail-host--hybrid");
      host.classList.add("access-drilldown-case-detail-host--row-form");
      appendRowFormFields(panel, enrichedRow, mapping);
      host.appendChild(panel);
      return;
    }
    const hybridStats = mappingHasTypicalCaseStats(mapping);
    if (hybridStats) {
      host.classList.add("access-drilldown-case-detail-host--hybrid");
    }
    applyCaseDetailWarningTone(panel, enrichedRow);

    const top = document.createElement("div");
    top.className = "access-drilldown-case-detail-top";
    if (mappingShowsHeader(mapping)) {
      appendCaseDetailHeader(top, enrichedRow, mapping, detail);
    }
    if (mappingShowsSummary(mapping)) {
      const summary = resolveCaseDetailFieldValue(enrichedRow, {
        field: String(mapping?.summary_field || mapping?.summaryField || "基本情况").trim(),
        fallback_fields: mapping?.summary_fallback_fields || mapping?.summaryFallbackFields,
      });
      const summaryBlock = document.createElement("div");
      summaryBlock.className = "access-drilldown-case-detail-summary";
      const summaryLabel = document.createElement("div");
      summaryLabel.className = "access-drilldown-case-detail-summary-label";
      summaryLabel.textContent = String(mapping?.summary_label || mapping?.summaryLabel || "基本情况").trim();
      const summaryText = document.createElement("div");
      summaryText.className = "access-drilldown-case-detail-summary-text";
      summaryText.textContent = summary || "—";
      summaryBlock.appendChild(summaryLabel);
      summaryBlock.appendChild(summaryText);
      top.appendChild(summaryBlock);
    }
    const factsOutsideBand =
      mapping?.facts_outside_band === true ||
      mapping?.factsOutsideBand === true ||
      cloneArray(mapping?.facts).length > 0;
    appendTypicalCaseStatsSection(top, enrichedRow, mapping, {
      wrapBand: hybridStats,
      config,
      factsOutsideBand,
    });
    if (mappingShowsMeta(mapping)) {
      appendCaseDetailMetaRow(top, enrichedRow, mapping);
    }
    if (mappingWantsRowForm(mapping)) {
      appendRowFormFields(top, enrichedRow, mapping);
    }
    panel.appendChild(top);

    const columnsRoot = document.createElement("div");
    columnsRoot.className = "access-drilldown-case-detail-columns";
    const columns = cloneArray(mapping?.columns);
    const laneCount = columns.length > 0 ? columns.length : 3;
    columnsRoot.style.setProperty("--case-detail-lane-count", String(laneCount));
    columnsRoot.dataset.laneCount = String(laneCount);
    columns.forEach((column) => {
      const columnEl = document.createElement("div");
      columnEl.className = "access-drilldown-case-detail-column";
      const columnId = String(column?.id || "").trim();
      if (columnId) {
        columnEl.dataset.caseDetailColumn = columnId;
      }
      const columnTitle = String(column?.title || column?.label || "").trim();
      if (columnTitle) {
        const titleEl = document.createElement("div");
        titleEl.className = "access-drilldown-case-detail-column-title";
        titleEl.textContent = columnTitle;
        columnEl.appendChild(titleEl);
      }
      cloneArray(column?.sections).forEach((section) => {
        appendCaseDetailSection(columnEl, section, enrichedRow, mapping, config);
      });
      if (columnEl.childElementCount) {
        columnsRoot.appendChild(columnEl);
      }
    });
    if (columnsRoot.childElementCount) {
      panel.appendChild(columnsRoot);
    } else {
      // 无泳道时顶区占满，避免空行留白。
      panel.style.gridTemplateRows = "minmax(0, 1fr)";
    }
    host.appendChild(panel);
    loadCaseCardDrilldownMeta();
  }

  function isTruthyFlag(value) {
    const text = String(value ?? "").trim();
    if (!text || text === "—" || text === "-" || text === "－" || text === "否" || text === "0") {
      return false;
    }
    if (text.includes("是")) return true;
    const numeric = Number(text.replace(/,/g, ""));
    return Number.isFinite(numeric) && numeric > 0;
  }

  function formatMetricValue(value, step) {
    const text = String(value ?? "").trim();
    if (!text) return "—";
    const numeric = Number(text.replace(/,/g, ""));
    if (!Number.isFinite(numeric) || numeric <= 0) return "—";
    const unit = String(step?.unit || "").trim();
    const formatted = Number.isInteger(numeric) ? String(numeric) : numeric.toFixed(2).replace(/\.?0+$/, "");
    return unit ? `${formatted}${unit}` : formatted;
  }

  function resolveSequentialStepStates(steps, row) {
    let lastActiveIndex = -1;
    steps.forEach((step, index) => {
      const field = String(step?.field || "").trim();
      if (!field) return;
      if (String(step?.kind || "flag").trim() === "metric") {
        const numeric = Number(String(row?.[field] ?? "").replace(/,/g, ""));
        if (Number.isFinite(numeric) && numeric > 0) {
          lastActiveIndex = index;
        }
        return;
      }
      if (isTruthyFlag(row?.[field])) {
        lastActiveIndex = index;
      }
    });
    return steps.map((step, index) => {
      const field = String(step?.field || "").trim();
      const kind = String(step?.kind || "flag").trim();
      if (kind === "metric") {
        const display = formatMetricValue(row?.[field], step);
        return {
          label: String(step?.label || field).trim(),
          state: display === "—" ? "pending" : "done",
          detail: display,
        };
      }
      const active = field ? isTruthyFlag(row?.[field]) : false;
      if (lastActiveIndex < 0) {
        return {
          label: String(step?.label || field).trim(),
          state: index === 0 ? "current" : "pending",
          detail: "",
        };
      }
      if (index < lastActiveIndex) {
        return { label: String(step?.label || field).trim(), state: "done", detail: "" };
      }
      if (index === lastActiveIndex) {
        return { label: String(step?.label || field).trim(), state: "current", detail: "" };
      }
      return { label: String(step?.label || field).trim(), state: "pending", detail: "" };
    });
  }

  function resolveListPreviewTitle(row, config, mapping) {
    const titleField = String(mapping?.title_field || mapping?.titleField || "").trim();
    if (titleField && row?.[titleField] != null && String(row[titleField]).trim()) {
      return String(row[titleField]).trim();
    }
    return resolveListPreviewRowTitle(row, config);
  }

  function appendSwimlaneSubtitle(panel, row, mapping) {
    const fields = cloneArray(mapping?.subtitle_fields || mapping?.subtitleFields);
    if (!fields.length) return;
    const meta = document.createElement("div");
    meta.className = "access-drilldown-swimlane-meta";
    fields.forEach((fieldName) => {
      const key = String(fieldName || "").trim();
      if (!key) return;
      const value = row?.[key];
      if (value == null || !String(value).trim()) return;
      const item = document.createElement("span");
      item.className = "access-drilldown-swimlane-meta-item";
      item.textContent = `${key}：${String(value).trim()}`;
      meta.appendChild(item);
    });
    if (meta.childElementCount) {
      panel.appendChild(meta);
    }
  }

  function appendSwimlaneContext(panel, row, mapping) {
    const contextField = String(mapping?.context_field || mapping?.contextField || "基本情况").trim();
    const value = row?.[contextField];
    if (value == null || !String(value).trim()) return;
    const block = document.createElement("div");
    block.className = "access-drilldown-swimlane-context";
    const label = document.createElement("div");
    label.className = "access-drilldown-swimlane-context-label";
    label.textContent = contextField;
    const text = document.createElement("div");
    text.className = "access-drilldown-swimlane-context-text";
    text.textContent = String(value).trim();
    block.appendChild(label);
    block.appendChild(text);
    panel.appendChild(block);
  }

  function renderSwimlaneNode(stepState) {
    const node = document.createElement("div");
    node.className = `access-drilldown-swimlane-node access-drilldown-swimlane-node--${stepState.state}`;
    const dot = document.createElement("span");
    dot.className = "access-drilldown-swimlane-node-dot";
    node.appendChild(dot);
    const label = document.createElement("span");
    label.className = "access-drilldown-swimlane-node-label";
    label.textContent = stepState.label;
    node.appendChild(label);
    if (stepState.detail && stepState.detail !== "—") {
      const detail = document.createElement("span");
      detail.className = "access-drilldown-swimlane-node-detail";
      detail.textContent = stepState.detail;
      node.appendChild(detail);
    }
    return node;
  }

  function renderSwimlanePreviewPanel(host, row, config) {
    if (!(host instanceof HTMLElement)) return;
    host.replaceChildren();
    if (!row || typeof row !== "object") {
      const empty = document.createElement("div");
      empty.className = "access-drilldown-list-preview-empty";
      empty.textContent = "点击清单中的案例查看办理泳道";
      host.appendChild(empty);
      return;
    }
    const mapping = resolveListPreviewMapping(config);
    if (!mapping) {
      renderListPreviewItemPanel(host, row, config);
      return;
    }
    const panel = document.createElement("div");
    panel.className = "access-drilldown-swimlane-panel";
    const title = document.createElement("div");
    title.className = "access-drilldown-swimlane-title";
    title.textContent = resolveListPreviewTitle(row, config, mapping);
    panel.appendChild(title);


/* ===== spa-navigation/drilldown/swimlane-preview/p3.js ===== */
    appendSwimlaneSubtitle(panel, row, mapping);
    appendSwimlaneContext(panel, row, mapping);

    const lanesRoot = document.createElement("div");
    lanesRoot.className = "access-drilldown-swimlane-lanes";
    cloneArray(mapping.lanes).forEach((lane) => {
      const laneEl = document.createElement("div");
      laneEl.className = "access-drilldown-swimlane-lane";
      const laneLabel = document.createElement("div");
      laneLabel.className = "access-drilldown-swimlane-lane-label";
      laneLabel.textContent = String(lane?.label || lane?.id || "流程").trim();
      laneEl.appendChild(laneLabel);
      const track = document.createElement("div");
      track.className = "access-drilldown-swimlane-track";
      const steps = cloneArray(lane?.steps);
      const stepStates = resolveSequentialStepStates(steps, row);
      stepStates.forEach((stepState, index) => {
        if (index > 0) {
          const connector = document.createElement("span");
          connector.className = "access-drilldown-swimlane-connector";
          connector.setAttribute("aria-hidden", "true");
          track.appendChild(connector);
        }
        track.appendChild(renderSwimlaneNode(stepState));
      });
      laneEl.appendChild(track);
      lanesRoot.appendChild(laneEl);
    });
    panel.appendChild(lanesRoot);
    host.appendChild(panel);
  }

  function normalizeUploadRelPath(relPath) {
    let path = String(relPath || "").trim().replace(/\\/g, "/");
    if (!path) return "";
    path = path.replace(/^\/+/, "");
    if (path.startsWith("upload/")) {
      path = path.slice("upload/".length);
    }
    return path;
  }

  function resolveUploadDownloadUrl(appId, relPath, options = {}) {
    const path = normalizeUploadRelPath(relPath);
    if (!path) return "";
    const app = String(appId || resolvePreviewAppId() || "").trim();
    if (!app) return "";
    const params = new URLSearchParams();
    params.set("path", path);
    if (options.inline) {
      params.set("inline", "true");
    }
    if (options.matchBasename) {
      params.set("match_basename", "true");
      const basename = String(options.basename || "").trim();
      if (basename) {
        params.set("basename", basename);
      }
    }
    return `/api/upload/download/${encodeURIComponent(app)}?${params.toString()}`;
  }

  function isDocumentPreviewPending(row, mapping) {
    const statusField = String(mapping?.status_field || mapping?.statusField || "附件状态").trim();
    const status = resolveCaseDetailFieldValue(row, { field: statusField });
    const pendingValues = cloneArray(mapping?.pending_status_values || mapping?.pendingStatusValues)
      .map((entry) => String(entry || "").trim())
      .filter(Boolean);
    if (pendingValues.length && pendingValues.includes(status)) return true;
    const docField = String(
      mapping?.document_path_field || mapping?.documentPathField || "附件相对路径",
    ).trim();
    return !resolveCaseDetailFieldValue(row, { field: docField });
  }

  function appendDocumentPreviewPlaceholder(panel, text, { hint = false } = {}) {
    const placeholder = document.createElement("div");
    placeholder.className = "access-drilldown-document-preview-empty";
    if (hint) {
      placeholder.classList.add("access-drilldown-document-preview-empty--hint");
    }
    placeholder.textContent = text;
    panel.appendChild(placeholder);
    return placeholder;
  }

  function createDocumentPreviewPanelShell({ title = "制度文件预览", idle = false } = {}) {
    const panel = document.createElement("div");
    panel.className = "access-drilldown-document-preview-panel";
    if (idle) {
      panel.classList.add("access-drilldown-document-preview-panel--idle");
    }
    const titleEl = document.createElement("div");
    titleEl.className = "access-drilldown-document-preview-title";
    titleEl.textContent = title;
    panel.appendChild(titleEl);
    return panel;
  }

  function renderDocumentPreviewPanel(host, row, config) {
    if (!(host instanceof HTMLElement)) return;
    host.replaceChildren();
    const mapping = resolveListPreviewMapping(config);
    if (!row || typeof row !== "object") {
      if (!mapping) {
        const empty = document.createElement("div");
        empty.className = "access-drilldown-list-preview-empty";
        empty.textContent = "点击清单中的条目查看详情";
        host.appendChild(empty);
        return;
      }
      const previewOnly = Boolean(mapping?.preview_only || mapping?.previewOnly);
      const panel = createDocumentPreviewPanelShell({
        idle: true,
        title: previewOnly ? "健全机制文档" : "制度文件预览",
      });
      appendDocumentPreviewPlaceholder(
        panel,
        previewOnly
          ? "正在加载制度文件…"
          : "点击左侧清单中的机制名称，在此预览 PDF 制度文件",
        { hint: true },
      );
      host.appendChild(panel);
      return;
    }
    if (!mapping) {
      renderListPreviewItemPanel(host, row, config);
      return;
    }
    const titleText = resolveCaseDetailFieldValue(row, {
      field: mapping?.title_field || mapping?.titleField || "机制名称",
      fallback_fields: mapping?.title_fallback_fields || mapping?.titleFallbackFields,
    });
    const panel = createDocumentPreviewPanelShell({ title: titleText });

    if (isDocumentPreviewPending(row, mapping)) {
      appendDocumentPreviewPlaceholder(panel, "制度文件待上传");
      host.appendChild(panel);
      return;
    }

    const docPath = resolveCaseDetailFieldValue(row, {
      field: mapping?.document_path_field || mapping?.documentPathField || "附件相对路径",
    });
    const src = resolveUploadDownloadUrl(
      mapping?.upload_app_id || mapping?.uploadAppId,
      docPath,
      { inline: true },
    );
    if (!src) {
      appendDocumentPreviewPlaceholder(panel, "暂无可预览的 PDF");
      host.appendChild(panel);
      return;
    }

    const frame = document.createElement("div");
    frame.className = "access-drilldown-document-preview-frame";
    frame.style.flex = "1 1 auto";
    frame.style.minHeight = "0";
    frame.style.height = "100%";
    const iframe = document.createElement("iframe");
    iframe.className = "access-drilldown-document-preview-iframe";
    iframe.style.width = "100%";
    iframe.style.height = "100%";
    iframe.style.border = "0";
    iframe.src = src;
    iframe.title = titleText || "PDF 预览";
    frame.appendChild(iframe);
    panel.appendChild(frame);
    host.appendChild(panel);
  }

  function resolveVideoPreviewSectionTitle(mapping, fallback = "视频预览") {
    const text = String(
      mapping?.video_section_title || mapping?.videoSectionTitle || fallback,
    ).trim();
    return text || fallback;
  }

  function resolveSummaryImageSectionTitle(mapping, fallback = "预警列表") {
    const text = String(
      mapping?.summary_image_section_title || mapping?.summaryImageSectionTitle || fallback,
    ).trim();
    return text || fallback;
  }

  function resolveSummaryImagePreviewUrl(row, mapping) {
    if (!row || typeof row !== "object" || !mapping || typeof mapping !== "object") return "";
    const dir = String(
      mapping?.summary_image_dir || mapping?.summaryImageDir || "预警摘要图片",
    ).trim();
    const idField = String(
      mapping?.summary_image_id_field || mapping?.summaryImageIdField || "视频编号",
    ).trim();
    const videoId = resolveCaseDetailFieldValue(row, { field: idField });
    if (!dir || !videoId) return "";
    return resolveUploadDownloadUrl(
      mapping?.upload_app_id || mapping?.uploadAppId,
      dir,
      { inline: true, matchBasename: true, basename: videoId },
    );
  }

  function resolveVideoPreviewPath(row, mapping) {
    if (!row || typeof row !== "object" || !mapping || typeof mapping !== "object") return "";
    const pathField = String(mapping?.video_path_field || mapping?.videoPathField || "视频路径").trim();
    let path = resolveCaseDetailFieldValue(row, { field: pathField });
    if (path) return path;
    const idField = String(mapping?.video_id_field || mapping?.videoIdField || "视频编号").trim();
    const videoId = resolveCaseDetailFieldValue(row, { field: idField });
    if (!videoId) return "";
    const prefix = String(mapping?.video_path_prefix || mapping?.videoPathPrefix || "videos/").trim();
    const suffix = String(mapping?.video_path_suffix || mapping?.videoPathSuffix || ".mp4").trim();
    return `${prefix}${videoId}${suffix}`;
  }


  function createVideoSubtitleCockpitShell({
    title = "视频预览",
    summaryTitle = "预警列表",
    idle = false,
  } = {}) {
    const panel = document.createElement("div");
    panel.className = "access-drilldown-video-cockpit-panel";
    if (idle) {
      panel.classList.add("access-drilldown-video-cockpit-panel--idle");
    }
    const videoSection = document.createElement("section");
    videoSection.className = "access-drilldown-video-cockpit-video";
    const videoTitle = document.createElement("div");
    videoTitle.className = "access-drilldown-video-cockpit-section-title";
    videoTitle.textContent = title;
    videoSection.appendChild(videoTitle);
    const videoFrame = document.createElement("div");
    videoFrame.className = "access-drilldown-video-cockpit-video-frame";
    videoSection.appendChild(videoFrame);
    const subtitleSection = document.createElement("section");
    subtitleSection.className = "access-drilldown-video-cockpit-subtitle access-drilldown-video-cockpit-summary-image";
    const subtitleTitle = document.createElement("div");
    subtitleTitle.className = "access-drilldown-video-cockpit-section-title";
    subtitleTitle.textContent = summaryTitle;
    subtitleSection.appendChild(subtitleTitle);
    const subtitleBody = document.createElement("div");
    subtitleBody.className = "access-drilldown-video-cockpit-subtitle-body access-drilldown-video-cockpit-summary-image-body";
    subtitleSection.appendChild(subtitleBody);
    panel.appendChild(videoSection);
    panel.appendChild(subtitleSection);
    return { panel, videoFrame, subtitleBody, videoTitle, subtitleTitle };
  }

  function appendVideoCockpitPlaceholder(frame, text, { hint = false } = {}) {
    const placeholder = document.createElement("div");
    placeholder.className = "access-drilldown-video-cockpit-empty";
    if (hint) {
      placeholder.classList.add("access-drilldown-video-cockpit-empty--hint");
    }
    placeholder.textContent = text;
    frame.appendChild(placeholder);
    return placeholder;
  }

  const SUMMARY_IMAGE_ZOOM_MIN = 1;
  const SUMMARY_IMAGE_ZOOM_MAX = 4;
  const SUMMARY_IMAGE_ZOOM_STEP = 1.25;

  function clampSummaryImageZoom(value) {
    const n = Number(value);
    if (!Number.isFinite(n)) return SUMMARY_IMAGE_ZOOM_MIN;
    return Math.min(SUMMARY_IMAGE_ZOOM_MAX, Math.max(SUMMARY_IMAGE_ZOOM_MIN, n));
  }

  function mountSummaryImagePanZoomControls(viewport, stage, tools) {
    let zoom = SUMMARY_IMAGE_ZOOM_MIN;
    let panX = 0;
    let panY = 0;
    let panMode = false;
    let dragState = null;
    const panButton = tools.querySelector('[data-summary-image-action="pan"]');

    const applyTransform = () => {
      stage.style.transform = `translate(${panX}px, ${panY}px) scale(${zoom})`;
    };

    const syncPanButton = () => {
      if (!(panButton instanceof HTMLButtonElement)) return;
      panButton.classList.toggle("is-active", panMode);
      panButton.setAttribute("aria-pressed", panMode ? "true" : "false");
    };

    const resetView = () => {
      zoom = SUMMARY_IMAGE_ZOOM_MIN;
      panX = 0;
      panY = 0;
      panMode = false;
      viewport.classList.remove("is-pan-active", "is-dragging");
      syncPanButton();
      applyTransform();
    };

    const setZoom = (nextZoom) => {
      zoom = clampSummaryImageZoom(nextZoom);
      applyTransform();
    };

    const canDrag = () => panMode || zoom > SUMMARY_IMAGE_ZOOM_MIN + 0.001;

    tools.addEventListener("click", (event) => {
      const button = event.target?.closest?.("[data-summary-image-action]");
      if (!(button instanceof HTMLButtonElement)) return;
      event.preventDefault();
      event.stopPropagation();
      const action = button.getAttribute("data-summary-image-action");
      if (action === "zoom-in") {
        setZoom(zoom * SUMMARY_IMAGE_ZOOM_STEP);
        return;
      }
      if (action === "zoom-out") {
        setZoom(zoom / SUMMARY_IMAGE_ZOOM_STEP);
        if (zoom <= SUMMARY_IMAGE_ZOOM_MIN + 0.001) {
          panX = 0;
          panY = 0;
          applyTransform();
        }
        return;
      }
      if (action === "pan") {
        panMode = !panMode;
        viewport.classList.toggle("is-pan-active", panMode);
        syncPanButton();
        return;
      }
      if (action === "reset") {
        resetView();
      }
    });

    viewport.addEventListener("pointerdown", (event) => {
      if (!canDrag()) return;
      if (event.button !== 0) return;
      if (event.target?.closest?.(".access-drilldown-video-cockpit-summary-image-tools")) return;
      dragState = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        originPanX: panX,
        originPanY: panY,
      };
      viewport.classList.add("is-dragging");
      if (typeof viewport.setPointerCapture === "function") {
        viewport.setPointerCapture(event.pointerId);
      }
      event.preventDefault();
    });

    const finishDrag = (event) => {
      if (!dragState) return;
      if (event.pointerId !== dragState.pointerId) return;
      dragState = null;
      viewport.classList.remove("is-dragging");
      if (typeof viewport.releasePointerCapture === "function") {
        try {
          viewport.releasePointerCapture(event.pointerId);
        } catch {
          // ignore stale capture
        }
      }
    };

    viewport.addEventListener("pointermove", (event) => {
      if (!dragState || event.pointerId !== dragState.pointerId) return;
      panX = dragState.originPanX + (event.clientX - dragState.startX);
      panY = dragState.originPanY + (event.clientY - dragState.startY);
      applyTransform();
      event.preventDefault();
    });
    viewport.addEventListener("pointerup", finishDrag);
    viewport.addEventListener("pointercancel", finishDrag);
    viewport.addEventListener("lostpointercapture", () => {
      dragState = null;
      viewport.classList.remove("is-dragging");
    });

    applyTransform();
    return { resetView };
  }

  function createSummaryImageViewport(image) {
    const viewport = document.createElement("div");
    viewport.className = "access-drilldown-video-cockpit-summary-image-viewport";

    const stage = document.createElement("div");
    stage.className = "access-drilldown-video-cockpit-summary-image-stage";
    stage.appendChild(image);

    const tools = document.createElement("div");
    tools.className = "access-drilldown-video-cockpit-summary-image-tools";
    tools.setAttribute("role", "group");
    tools.setAttribute("aria-label", "摘要图片缩放");
    tools.innerHTML = `
      <button type="button" data-summary-image-action="zoom-in" title="放大" aria-label="放大">+</button>
      <button type="button" data-summary-image-action="zoom-out" title="缩小" aria-label="缩小">−</button>
      <button type="button" data-summary-image-action="pan" title="拖拽平移" aria-label="拖拽平移" aria-pressed="false">✋</button>
      <button type="button" data-summary-image-action="reset" title="复原视图" aria-label="复原视图">◎</button>
    `;

    viewport.appendChild(stage);
    viewport.appendChild(tools);
    mountSummaryImagePanZoomControls(viewport, stage, tools);
    return viewport;
  }

  function renderSummaryImagePreview(subtitleBody, row, mapping) {
    if (!(subtitleBody instanceof HTMLElement)) return;
    subtitleBody.replaceChildren();
    const src = resolveSummaryImagePreviewUrl(row, mapping);
    if (!src) {
      subtitleBody.textContent = "暂无预警摘要图片";
      return;
    }
    const image = document.createElement("img");
    image.className = "access-drilldown-video-cockpit-summary-image-img";
    image.alt = "预警摘要图片";
    image.loading = "lazy";
    image.decoding = "async";
    image.draggable = false;
    image.src = src;
    image.addEventListener("error", () => {
      subtitleBody.replaceChildren();
      appendVideoCockpitPlaceholder(subtitleBody, "未找到匹配的预警摘要图片，请确认已上传");
    });
    subtitleBody.appendChild(createSummaryImageViewport(image));
  }

  function renderVideoSubtitleCockpitPanel(host, row, config) {
    if (!(host instanceof HTMLElement)) return;
    host.replaceChildren();
    const mapping = resolveListPreviewMapping(config);
    if (!mapping) {
      const empty = document.createElement("div");
      empty.className = "access-drilldown-list-preview-empty";
      empty.textContent = "点击清单中的条目查看详情";
      host.appendChild(empty);
      return;
    }
    const videoSectionTitle = resolveVideoPreviewSectionTitle(mapping);
    const summarySectionTitle = resolveSummaryImageSectionTitle(mapping);
    if (!row || typeof row !== "object") {
      const { panel, videoFrame, subtitleBody } = createVideoSubtitleCockpitShell({
        title: videoSectionTitle,
        summaryTitle: summarySectionTitle,
        idle: true,
      });
      appendVideoCockpitPlaceholder(
        videoFrame,
        "请选择预警记录或上传视频",
        { hint: true },
      );
      subtitleBody.textContent = "请选择预警记录查看摘要图片";
      host.appendChild(panel);
      return;
    }
    const titleText = resolveCaseDetailFieldValue(row, {
      field: mapping?.title_field || mapping?.titleField || "视频编号",
      fallback_fields: mapping?.title_fallback_fields || mapping?.titleFallbackFields,
    });
    const { panel, videoFrame, subtitleBody, videoTitle, subtitleTitle } = createVideoSubtitleCockpitShell({
      title: videoSectionTitle,
      summaryTitle: summarySectionTitle,
    });
    if (videoTitle instanceof HTMLElement) {
      videoTitle.textContent = titleText
        ? `${videoSectionTitle} · ${titleText}`
        : videoSectionTitle;
    }
    if (subtitleTitle instanceof HTMLElement) {
      subtitleTitle.textContent = summarySectionTitle;
    }
    const relPath = resolveVideoPreviewPath(row, mapping);
    const src = resolveUploadDownloadUrl(
      mapping?.upload_app_id || mapping?.uploadAppId,
      relPath,
      { inline: true },
    );
    if (!src) {
      appendVideoCockpitPlaceholder(videoFrame, "暂无可预览的视频");
    } else {
      const video = document.createElement("video");
      video.className = "access-drilldown-video-cockpit-player";
      video.controls = true;
      video.preload = "metadata";
      video.playsInline = true;
      video.src = src;
      video.title = titleText || "执法视频预览";
      video.addEventListener("error", () => {
        videoFrame.replaceChildren();
        appendVideoCockpitPlaceholder(videoFrame, "未找到可播放的视频文件，请确认视频路径已上传");
      });
      videoFrame.appendChild(video);
    }
    renderSummaryImagePreview(subtitleBody, row, mapping);
    host.appendChild(panel);
  }


/* ===== spa-navigation/drilldown/render-list-preview.js ===== */
  const LIST_PREVIEW_ROW_SELECT_EVENT = "mei:table-row-select";

  function resolveListPreviewFields(config) {
    const previewFields = cloneArray(config?.rowPreviewSlot?.fields || config?.previewSlot?.fields);
    if (previewFields.length) return previewFields;
    const listFields = cloneArray(config?.detailSlot?.fields || config?.listSlot?.fields);
    if (listFields.length) return listFields;
    return cloneArray(config?.columns);
  }

  function resolveListPreviewRowTitle(row, config) {
    if (!row || typeof row !== "object") return "条目详情";
    for (const key of ["label", "title", "name", "名称", "标题"]) {
      const value = row[key];
      if (value != null && String(value).trim()) {
        return String(value).trim();
      }
    }
    for (const field of resolveListPreviewFields(config)) {
      const key = String(field?.column || field?.key || field || "").trim();
      if (!key) continue;
      const value = row[key];
      if (value != null && String(value).trim()) {
        return String(value).trim();
      }
    }
    for (const value of Object.values(row)) {
      if (value != null && String(value).trim() && typeof value !== "object") {
        return String(value).trim();
      }
    }
    return "条目详情";
  }

  function renderListPreviewItemPanel(host, row, config) {
    if (!(host instanceof HTMLElement)) return;
    if (isTypicalCaseCardPreview(config)) {
      renderTypicalCaseCardPanel(host, row, config, config?.drilldownDetail);
      return;
    }
    if (isCaseDetailCardPreview(config)) {
      renderCaseDetailCardPanel(host, row, config, config?.drilldownDetail);
      return;
    }
    if (isSwimlanePreview(config)) {
      renderSwimlanePreviewPanel(host, row, config);
      return;
    }
    if (isDocumentPreview(config)) {
      renderDocumentPreviewPanel(host, row, config);
      return;
    }
    if (isVideoSubtitleCockpitPreview(config)) {
      renderVideoSubtitleCockpitPanel(host, row, config);
      return;
    }
    host.replaceChildren();
    if (!row || typeof row !== "object") {
      const empty = document.createElement("div");
      empty.className = "access-drilldown-list-preview-empty";
      empty.textContent = "点击清单中的条目查看详情";
      host.appendChild(empty);
      return;
    }
    const panel = document.createElement("div");
    panel.className = "access-drilldown-list-preview-panel";
    const title = document.createElement("div");
    title.className = "access-drilldown-list-preview-title";
    title.textContent = resolveListPreviewRowTitle(row, config);
    panel.appendChild(title);
    const fields = resolveListPreviewFields(config);
    const entries =
      fields.length > 0
        ? fields.map((field) => {
            const key = String(field?.column || field?.key || field || "").trim();
            if (!key) return null;
            const label = String(field?.label || key).trim();
            const value = row?.[key];
            return { label, value };
          })
        : Object.entries(row).map(([key, value]) => ({ label: key, value }));
    const list = document.createElement("dl");
    list.className = "access-drilldown-list-preview-fields";
    entries
      .filter(Boolean)
      .forEach((entry) => {
        const dt = document.createElement("dt");
        dt.textContent = entry.label;
        const dd = document.createElement("dd");
        dd.textContent =
          entry.value === null || entry.value === undefined ? "" : String(entry.value);
        list.appendChild(dt);
        list.appendChild(dd);
      });
    panel.appendChild(list);
    host.appendChild(panel);
  }

  function cleanupListPreviewDrilldownWatcher(root) {
    if (!(root instanceof HTMLElement)) return;
    const cleanup = root.__meiListPreviewQueryStateCleanup;
    if (typeof cleanup === "function") {
      cleanup();
    }
    root.__meiListPreviewQueryStateCleanup = null;
    const rowSelectCleanup = root.__meiListPreviewRowSelectCleanup;
    if (typeof rowSelectCleanup === "function") {
      rowSelectCleanup();
    }
    root.__meiListPreviewRowSelectCleanup = null;
  }

  async function renderListPreviewDrilldownContent(root, detail, config) {
    applyDrilldownOverlayMeta(root, config);
    setDrilldownOverlayStatus(root, "loading");
    cleanupListPreviewDrilldownWatcher(root);
    const listHost = root.querySelector('[data-drilldown-list-host="true"]');
    const previewHost = root.querySelector('[data-drilldown-preview-host="true"]');
    if (!(listHost instanceof HTMLElement) || !(previewHost instanceof HTMLElement)) {
      setDrilldownOverlayStatus(root, "error", {
        message: "清单预览看板缺少列表或预览挂载节点",
        phase: "list_preview_host_missing",
        detail,
        config,
      });
      return false;
    }
    listHost.replaceChildren();
    renderListPreviewItemPanel(previewHost, null, config);
    const listSlot = config?.listSlot || config?.detailSlot;
    const listConfig = listSlot
      ? {
          ...resolveDrilldownTabConfig(config, listSlot.id),
          listPreviewDrilldown: true,
          queryStateId: config.queryStateId,
          columns: cloneArray(listSlot.fields).length
            ? cloneArray(listSlot.fields)
            : cloneArray(resolveDrilldownTabConfig(config, listSlot.id).columns),
        }
      : { ...config, listPreviewDrilldown: true };
    try {
      const filterHost = root.querySelector(
        '[data-drilldown-body-mode="list-preview"] [data-drilldown-filter-host="true"]',
      );
      await mountAnalyticsFilterBar(root, detail, config, filterHost);
      const tableOk = await mountDrilldownTable(root, detail, listConfig, listHost);
      if (!tableOk) {
        setDrilldownOverlayStatus(root, "error", {
          message: "清单预览明细表挂载失败",
          phase: "list_preview_table_mount_failed",
          detail,
          config: listConfig,
        });
        return false;
      }
      const onRowSelect = (event) => {
        if (event?.detail?.query_state_id && event.detail.query_state_id !== config?.queryStateId) {
          return;
        }
        renderListPreviewItemPanel(previewHost, event?.detail?.row || null, config);
      };
      listHost.addEventListener(LIST_PREVIEW_ROW_SELECT_EVENT, onRowSelect);
      root.__meiListPreviewRowSelectCleanup = () => {
        listHost.removeEventListener(LIST_PREVIEW_ROW_SELECT_EVENT, onRowSelect);
      };
      const queryStateId = nonEmptyString(config?.queryStateId, detail?.query_state_id, detail?.queryStateId);
      if (queryStateId) {
        const onQueryStateChange = (event) => {
          if (event?.detail?.id !== queryStateId) return;
          if (!(root instanceof HTMLElement) || root.hasAttribute("hidden")) return;
          // 明细表已 subscribeQueryState；不要 remount，否则与进行中请求竞态盖掉筛选结果。
          renderListPreviewItemPanel(previewHost, null, config);
          dispatchPreviewUpdated("drilldown");
        };
        window.addEventListener("mei:query-state-change", onQueryStateChange);
        root.__meiListPreviewQueryStateCleanup = () => {
          window.removeEventListener("mei:query-state-change", onQueryStateChange);
        };
      }
      setDrilldownOverlayStatus(root, "ready");
      dispatchPreviewUpdated("drilldown");
      return true;
    } catch (error) {
      recordPopupDebugIssue({
        level: "error",
        message: String(error?.message || error || "清单预览看板渲染失败"),
        phase: "list_preview_render_error",
        detail,
        config,
        root,
        stack: error?.stack || "",
      });
      setDrilldownOverlayStatus(root, "error");
      return false;
    }
  }



/* ===== spa-navigation/drilldown/render-structured.js ===== */
  function cleanupStructuredDrilldownWatcher(root) {
    if (!(root instanceof HTMLElement)) return;
    cleanupAnalyticsDrilldownWatcher(root);
    cleanupListPreviewDrilldownWatcher(root);
    const queryCleanup = root.__meiStructuredQueryStateCleanup;
    if (typeof queryCleanup === "function") {
      queryCleanup();
    }
    root.__meiStructuredQueryStateCleanup = null;
    const rowCleanup = root.__meiStructuredRowSelectionCleanup;
    if (typeof rowCleanup === "function") {
      rowCleanup();
    }
    root.__meiStructuredRowSelectionCleanup = null;
  }

  function boardLayoutAreasCss(areas = []) {
    if (!Array.isArray(areas) || areas.length === 0) return "";
    return areas
      .filter((row) => Array.isArray(row) && row.length > 0)
      .map((row) =>
        `"${row
          .map((entry) => {
            const token = String(entry || "").trim();
            // MeiLang `_` empty cell → CSS null cell `.`
            return !token || token === "_" ? "." : token;
          })
          .join(" ")}"`,
      )
      .join(" ");
  }

  function applySceneShellLayout(node, layout) {
    if (!(node instanceof HTMLElement)) return;
    node.style.display = "grid";
    node.style.gridTemplateColumns =
      Array.isArray(layout?.columns) && layout.columns.length ? layout.columns.join(" ") : "";
    node.style.gridTemplateRows =
      Array.isArray(layout?.rows) && layout.rows.length ? layout.rows.join(" ") : "";
    node.style.gridTemplateAreas = boardLayoutAreasCss(layout?.areas);
    node.style.gap = nonEmptyString(layout?.gap);
    node.style.padding = nonEmptyString(layout?.padding);
  }

  /** Analytics / list_preview T2：锁住 region/section 等价配额，禁止内容后加载撑开壳。 */
  function lockStructuredShellFill(node, { scrollable = false } = {}) {
    if (!(node instanceof HTMLElement)) return;
    node.style.minHeight = "0";
    node.style.minWidth = "0";
    node.style.height = "100%";
    node.style.boxSizing = "border-box";
    node.style.overflow = scrollable ? "auto" : "hidden";
  }

  function ensureStructuredDrilldownZoneHosts(root, sceneShell) {
    const layoutHost = root.querySelector('[data-drilldown-structured-layout="true"]');
    if (!(layoutHost instanceof HTMLElement) || !sceneShell) return null;
    layoutHost.replaceChildren();
    layoutHost.dataset.shellLayoutMode = String(sceneShell.layoutMode || "");
    applySceneShellLayout(layoutHost, sceneShell.layout);
    const layoutMode = String(sceneShell.layoutMode || "");
    const fillLock = layoutMode === "analytics" || layoutMode === "list_preview";
    if (fillLock) {
      lockStructuredShellFill(layoutHost);
      const shell = layoutHost.closest(".access-drilldown-structured-shell");
      if (shell instanceof HTMLElement) {
        shell.style.minHeight = "0";
        shell.style.flex = "1";
        shell.style.height = "100%";
        shell.style.overflow = "hidden";
      }
    }
    const zoneHosts = {};
    const zones = Array.isArray(sceneShell.zones) ? sceneShell.zones : [];
    const childrenByParent = new Map();
    zones.forEach((zone) => {
      const parent = nonEmptyString(zone?.parent);
      if (!childrenByParent.has(parent)) childrenByParent.set(parent, []);
      childrenByParent.get(parent).push(zone);
    });

    const createZoneNode = (zone) => {
      const wrapper = document.createElement(zone.role === "filter" || zone.role === "row_preview" ? "aside" : "div");
      wrapper.className = "access-drilldown-shell-zone";
      wrapper.dataset.shellZoneId = zone.id;
      wrapper.dataset.shellZoneRole = zone.role;
      if (zone.area) {
        wrapper.style.gridArea = zone.area;
      }
      if (fillLock) {
        lockStructuredShellFill(wrapper);
      }
      if (zone.role === "container") {
        wrapper.classList.add("access-drilldown-shell-zone--container");
        applySceneShellLayout(wrapper, zone.layout);
        if (fillLock) {
          lockStructuredShellFill(wrapper);
        }
      } else {
        const host =
          zone.role === "filter" || zone.role === "tab_bar"
            ? wrapper
            : (() => {
                const surface = document.createElement("div");
                surface.className = "access-drilldown-shell-surface";
                wrapper.appendChild(surface);
                return surface;
              })();
        host.classList.add("access-drilldown-shell-host");
        host.dataset.drilldownZoneHost = zone.id;
        if (fillLock) {
          // list / detail / 行级详情卡（预警详情、典型案例等 preview）需在 host 内滚动；
          // 勿对 row_preview 写 overflow:hidden，否则会盖过 CSS 的 overflow:auto 导致内容截断。
          const scrollable =
            zone.id === "detail" ||
            zone.id === "list" ||
            zone.id === "preview" ||
            zone.role === "list" ||
            zone.role === "row_preview";
          lockStructuredShellFill(host, { scrollable });
          if (zone.role === "filter") {
            host.style.overflow = "visible";
            if (host !== wrapper) {
              wrapper.style.overflow = "visible";
            }
          }
          if (host !== wrapper) {
            lockStructuredShellFill(wrapper);
            if (zone.role === "filter") {
              wrapper.style.overflow = "visible";
            }
          }
        }
        zoneHosts[zone.id] = host;
      }
      const children = childrenByParent.get(zone.id) || [];
      children.forEach((child) => wrapper.appendChild(createZoneNode(child)));
      return wrapper;
    };

    const rootZones = childrenByParent.get("") || [];
    rootZones.forEach((zone) => layoutHost.appendChild(createZoneNode(zone)));
    return zoneHosts;
  }

  async function mountStructuredSlotZone(root, detail, config, zone, host) {
    if (!(host instanceof HTMLElement)) return false;
    host.replaceChildren();
    host.style.gridTemplateColumns = "";
    const zoneSlots = Array.isArray(config?.slotsByZone?.[zone.id]) ? config.slotsByZone[zone.id] : [];
    if (!zoneSlots.length) {
      return !zone.required;
    }
    if (zoneSlots.every((slot) => slot.component === "chart")) {
      zoneSlots.forEach((slot, index) => {
        const slotEl = document.createElement("div");
        slotEl.className = "access-drilldown-shell-slot access-drilldown-shell-slot--chart";
        slotEl.dataset.chartSlotIndex = String(index);
        if (slot?.id) slotEl.dataset.buildBoardSlot = String(slot.id);
        host.appendChild(slotEl);
      });
      host.style.display = "grid";
      host.style.gridTemplateColumns =
        zoneSlots.length > 1 ? `repeat(${zoneSlots.length}, minmax(0, 1fr))` : "1fr";
      return mountAnalyticsChartSlots(root, detail, config, zoneSlots, host);
    }
    const primarySlot = zoneSlots[0];
    const baseConfig = resolveDrilldownTabConfig(config, primarySlot.id);
    const slotConfig = {
      ...baseConfig,
      queryStateId: config.queryStateId,
      hasChartZone: config.hasChartZone,
      hasRowPreviewZone: config.hasRowPreviewZone,
      tableMetricId: nonEmptyString(
        primarySlot.metricId,
        baseConfig.tableMetricId,
        config.tableMetricId,
        resolveDrilldownTableMetricId(detail, config),
      ),
      datasetId: nonEmptyString(primarySlot.datasetId, baseConfig.datasetId, config.datasetId),
      columns: cloneArray(primarySlot.fields).length
        ? cloneArray(primarySlot.fields)
        : cloneArray(baseConfig.columns),
      column_state:
        primarySlot.columnState && typeof primarySlot.columnState === "object"
          ? primarySlot.columnState
          : baseConfig.column_state,
      pageSize: positiveInt(primarySlot.pageSize, primarySlot.page_size) || baseConfig.pageSize,
      column_template: nonEmptyString(
        primarySlot.columnTemplate,
        primarySlot.column_template,
        baseConfig.column_template,
      ),
      column_formats:
        primarySlot.columnFormats && typeof primarySlot.columnFormats === "object"
          ? primarySlot.columnFormats
          : baseConfig.column_formats,
      rowSelectionMode:
        config?.rowPreviewSourceZoneId && config.rowPreviewSourceZoneId === zone.id ? "single" : "",
    };
    if (primarySlot.component === "data_table") {
      host.dataset.buildBoardSlot = primarySlot.id;
      return mountDrilldownTable(root, detail, { ...config, ...slotConfig }, host);
    }
    if (primarySlot.component === "summary" || primarySlot.component === "metric_card") {
      const summaryNode = createDrilldownSummaryNode(slotConfig, primarySlot.id);
      summaryNode.dataset.buildBoardSlot = primarySlot.id;
      host.appendChild(summaryNode);
      return true;
    }
    return false;
  }

  async function mountPreviewOnlyCaseDetail(root, detail, config, zoneHosts) {
    const mapping = resolveListPreviewMapping(config);
    if (!isPreviewOnlyMapping(config) && !isSheetDetailCardPreview(config)) {
      return false;
    }
    const previewZoneId = nonEmptyString(config?.rowPreviewZoneId);
    const previewHost = zoneHosts?.[previewZoneId];
    if (!(previewHost instanceof HTMLElement)) return false;
    root.dataset.drilldownPreviewOnly = "true";
    const layoutHost = root.querySelector('[data-drilldown-structured-layout="true"]');
    if (layoutHost instanceof HTMLElement) {
      layoutHost.style.gridTemplateColumns = "1fr";
      layoutHost.style.gridTemplateAreas = '"preview"';
    }
    root.querySelectorAll(".access-drilldown-shell-zone").forEach((zone) => {
      if (!(zone instanceof HTMLElement)) return;
      const role = String(zone.dataset.shellZoneRole || "").trim();
      if (role === "filter" || role === "slots") {
        zone.hidden = true;
      }
      if (role === "row_preview") {
        zone.style.gridArea = "preview";
      }
    });
    const renderPreviewOnlyPanel = (row) => {
      // 健全机制等 document_preview：只渲染 PDF，禁止走典型案例/case 卡壳。
      if (isDocumentPreview(config)) {
        renderListPreviewItemPanel(previewHost, row, { ...config, drilldownDetail: detail });
        return;
      }
      renderSheetDetailCardPanel(
        previewHost,
        row ? enrichCaseDetailRow(row, detail) : null,
        config,
        detail,
      );
    };
    renderPreviewOnlyPanel(null);
    try {
      const fetchConfig = {
        ...config,
        drilldownDetail: detail,
        previewCompileAnchor: {
          sceneId: nonEmptyString(
            config?.previewCompileAnchor?.sceneId,
            config?.boardSceneId,
            detail?.board_scene_id,
            detail?.popup?.scene_id,
          ),
          scenePath: nonEmptyString(
            config?.previewCompileAnchor?.scenePath,
            config?.boardSceneFile,
            detail?.board_scene_file,
            detail?.popup?.scene_file,
          ),
          ownerScenePath: nonEmptyString(
            config?.previewCompileAnchor?.ownerScenePath,
            importedCapsuleScenePathFromMetricId(
              resolvePopupPassedMetricId(detail, config) || config?.tableMetricId,
            ),
          ),
        },
        tableMetricId: nonEmptyString(
          // preview-only / document_preview：优先用 rowPreview 的 explain 子 metric
          //（如 mechanism_document_detail::mechanism_document_preview），勿先落到 parent::__scalar_rowset__。
          config?.rowPreviewSlot?.metricId,
          config?.tableMetricId,
          resolvePopupPassedMetricId(detail, config),
        ),
      };
      const parentMetricId = nonEmptyString(
        resolvePopupPassedMetricId(detail, config),
        config?.tableMetricId,
      );
      const explainBlockId = nonEmptyString(
        config?.rowPreviewSlot?.explainBlockId,
        config?.rowPreviewSlot?.id,
      );
      if (
        parentMetricId &&
        explainBlockId &&
        !String(fetchConfig.tableMetricId || "").includes("::") &&
        typeof resolveCompositionScopedMetricId === "function"
      ) {
        const scoped = resolveCompositionScopedMetricId(parentMetricId, explainBlockId);
        if (scoped) fetchConfig.tableMetricId = scoped;
      }
      const dataset = await fetchPopupDrilldownRows(detail, fetchConfig);
      const rows = Array.isArray(dataset?.rows) ? dataset.rows : [];
      const matched = pickRowMatchingDrilldownFilters(rows, detail);
      renderPreviewOnlyPanel(matched || null);
      return true;
    } catch (error) {
      const isDoc = isDocumentPreview(config);
      const traceId = recordPopupDebugIssue({
        level: "error",
        message: String(
          error?.message || error || (isDoc ? "健全机制文档加载失败" : "典型案例详情卡加载失败"),
        ),
        phase: isDoc ? "mechanism_document_preview_fetch_error" : "case_detail_card_fetch_error",
        detail,
        config,
        root,
        stack: error?.stack || "",
      });
      renderPreviewOnlyPanel(null);
      const empty = previewHost.querySelector(".access-drilldown-list-preview-empty");
      if (empty instanceof HTMLElement) {
        empty.textContent = traceId
          ? `${isDoc ? "文档预览" : "案例详情"}加载失败（追踪编号：${traceId}）`
          : `${isDoc ? "文档预览" : "案例详情"}加载失败`;
      }
      return false;
    }
  }

  function mountStructuredRowPreviewZone(root, zoneHosts, config) {
    const previewZoneId = nonEmptyString(config?.rowPreviewZoneId);
    const sourceZoneId = nonEmptyString(config?.rowPreviewSourceZoneId);
    if (!previewZoneId || !sourceZoneId) return;
    const previewHost = zoneHosts?.[previewZoneId];
    const sourceHost = zoneHosts?.[sourceZoneId];
    if (!(previewHost instanceof HTMLElement) || !(sourceHost instanceof HTMLElement)) return;
    renderListPreviewItemPanel(previewHost, null, config);
    const onRowSelect = (event) => {
      if (event?.detail?.query_state_id && event.detail.query_state_id !== config?.queryStateId) {
        return;
      }
      renderListPreviewItemPanel(previewHost, event?.detail?.row || null, config);
    };
    sourceHost.addEventListener(LIST_PREVIEW_ROW_SELECT_EVENT, onRowSelect);
    root.__meiStructuredRowSelectionCleanup = () => {
      sourceHost.removeEventListener(LIST_PREVIEW_ROW_SELECT_EVENT, onRowSelect);
    };
  }

  function renderStructuredTabZones(root, detail, config, zoneHosts) {
    const tabsHost = zoneHosts?.[config?.tabBarZoneId];
    const contentHost = zoneHosts?.[config?.tabContentZoneId];
    if (!(tabsHost instanceof HTMLElement) || !(contentHost instanceof HTMLElement)) {
      return false;
    }
    const activeTab = renderDrilldownTabs(root, detail, config, tabsHost, contentHost);
    return renderDrilldownContent(root, detail, config, activeTab, contentHost);
  }

  async function renderStructuredDrilldownContent(root, detail, config) {
    applyDrilldownOverlayMeta(root, config);
    setDrilldownOverlayStatus(root, "loading");
    cleanupStructuredDrilldownWatcher(root);
    const zoneHosts = ensureStructuredDrilldownZoneHosts(root, config?.sceneShell);
    if (!zoneHosts) {
      setDrilldownOverlayStatus(root, "error", {
        message: "结构化看板缺少布局挂载节点",
        phase: "structured_shell_host_missing",
        detail,
        config,
      });
      return false;
    }
    root.__meiStructuredZoneHosts = zoneHosts;
    try {
      await prefetchStructuredDrilldownWidgets(config);
      if (config?.sceneShell?.layoutMode === "generic_tabs") {
        const ok = renderStructuredTabZones(root, detail, config, zoneHosts);
        if (!ok) {
          setDrilldownOverlayStatus(root, "error", {
            message: "结构化看板标签区域挂载失败",
            phase: "structured_tab_mount_failed",
            detail,
            config,
          });
          return false;
        }
        return true;
      }
      const filterZone = sceneShellZonesByRole(config?.sceneShell, "filter")[0] || null;
      if (filterZone && zoneHosts[filterZone.id] instanceof HTMLElement) {
        await mountAnalyticsFilterBar(root, detail, config, zoneHosts[filterZone.id]);
      }
      const slotZones = sceneShellZonesByRole(config?.sceneShell, "slots");
      for (const zone of slotZones) {
        const ok = await mountStructuredSlotZone(root, detail, config, zone, zoneHosts[zone.id]);
        if (!ok) {
          setDrilldownOverlayStatus(root, "error", {
            message: `结构化看板区域挂载失败：${String(zone?.id || "unknown")}`,
            phase: "structured_slot_mount_failed",
            detail,
            config,
          });
          return false;
        }
      }
      if (await mountPreviewOnlyCaseDetail(root, detail, config, zoneHosts)) {
        setDrilldownOverlayStatus(root, "ready");
        dispatchPreviewUpdated("drilldown");
        return true;
      }
      mountStructuredRowPreviewZone(root, zoneHosts, config);
      bindAnalyticsChartsQueryStateRefresh(root, detail, config, (zoneId) => zoneHosts?.[zoneId]);
      root.__meiStructuredQueryStateCleanup = root.__meiAnalyticsQueryStateCleanup;
      setDrilldownOverlayStatus(root, "ready");
      dispatchPreviewUpdated("drilldown");
      return true;
    } catch (error) {
      recordPopupDebugIssue({
        level: "error",
        message: String(error?.message || error || "通用下钻壳渲染失败"),
        phase: "structured_shell_render_error",
        detail,
        config,
        root,
        stack: error?.stack || "",
      });
      setDrilldownOverlayStatus(root, "error");
      return false;
    }
  }



/* ===== spa-navigation/drilldown/render-derived.js ===== */
  async function mountDerivedDrilldownContent(root, detail, config, tabId, hostOverride = null) {
    const host =
      hostOverride instanceof HTMLElement
        ? hostOverride
        : root.querySelector('[data-drilldown-table-host="true"]');
    if (!(host instanceof HTMLElement)) {
      return false;
    }
    const datasetId = resolveDrilldownDatasetId(detail, config);
    if (!datasetId) {
      recordPopupDebugIssue({
        level: "error",
        message: "未解析到 explain 派生块需要的数据集 id",
        phase: "derived_dataset_missing",
        detail,
        config,
        root,
      });
      return false;
    }
    // 构成/趋势派生必须用看板分析指标（popup / tableMetricId），勿用入口 KPI count，
    // 否则有 default_filters 时会走 useDetailRowset → count::__scalar_rowset__ → 500。
    const cardMetricId = nonEmptyString(
      config?.tableMetricId,
      resolvePopupPassedMetricId(detail, config),
      detail?.metric_id,
      detail?.__mei_runtime_ref?.metric_id,
    );
    const fetchConfig = { ...config, datasetId };
    const sharedQueryStateId = nonEmptyString(
      config?.queryStateId,
      detail?.query_state_id,
      detail?.queryStateId,
    );
    const isCompositionTab =
      explainMetricKind(config, tabId) === "composition" ||
      nonEmptyString(config?.supportRole).toLowerCase() === "composition" ||
      isVerifiedShareCompositionTab(tabId, config);
    const isTrendTab =
      explainMetricKind(config, tabId) === "trend" ||
      nonEmptyString(config?.supportRole).toLowerCase() === "trend";
    const verifiedShare = isVerifiedShareCompositionTab(tabId, config);
    const useDetailRowset = Boolean(
      cardMetricId &&
        (isCompositionTab || isTrendTab) &&
        (verifiedShare ||
          (sharedQueryStateId && hasActiveDrilldownQueryFilters(sharedQueryStateId))),
    );
    if (useDetailRowset) {
      // 查实占比与有筛选的构成图：一律拉当前明细 scalar rowset 再聚合（单一真源）。
      fetchConfig.tableMetricId = resolveCardMetricRowsetId(cardMetricId);
      fetchConfig.supportRole = "";
      fetchConfig.clientAggregate = true;
    } else if (cardMetricId && isCompositionTab) {
      const slotMetricId = nonEmptyString(config?.tableMetricId);
      const compositionMetricId = resolveCompositionScopedMetricId(cardMetricId, tabId);
      if (isDedicatedExplainMetricId(slotMetricId, { supportRole: config?.supportRole })) {
        fetchConfig.tableMetricId = slotMetricId;
      } else if (compositionMetricId) {
        fetchConfig.tableMetricId = compositionMetricId;
        fetchConfig.supportRole = "composition";
      }
    } else if (cardMetricId && isTrendTab) {
      fetchConfig.tableMetricId = resolveCardMetricRowsetId(cardMetricId);
    }
    const dataset = await fetchPopupDrilldownRows(detail, fetchConfig);
    const rows = Array.isArray(dataset?.rows) ? dataset.rows : [];
    if (!rows.length) {
      recordPopupDebugIssue({
        level: "warn",
        message: "popup panel 派生查询返回 0 行，已回退到摘要说明",
        phase: "derived_dataset_empty",
        detail,
        config,
        datasetId,
      });
    }
    if (explainMetricKind(config, tabId) === "composition" || isVerifiedShareCompositionTab(tabId, config)) {
      const columns = Array.isArray(dataset?.columns) ? dataset.columns : [];
      const verifiedShare = isVerifiedShareCompositionTab(tabId, config);
      const dimension = verifiedShare ? "查实占比" : compositionFieldForTab(config, tabId);
      if (!dimension && !verifiedShare) {
        recordPopupDebugIssue({
          level: "error",
          message: `构成 tab 未解析到分组字段（tab=${normalizeTabId(tabId)}）`,
          phase: "derived_composition_dimension_missing",
          detail,
          config,
          datasetId,
          root,
        });
        return false;
      }
      const grouped = limitCompositionRows(
        verifiedShare
          ? groupRowsForVerifiedShare(rows, columns)
          : groupRowsForComposition(rows, dimension, columns, config, detail),
        config,
      );
      if (!grouped.length) return false;
      const chartTag = drilldownChartTag(config?.chartKind, tabId) || "mei-chart-bar";
      const registered = await ensureDrilldownChartRegistered(chartTag);
      if (!registered) return false;
      resetDrilldownChartSlotHost(
        host,
        resolveDrilldownChartSlotCaption(config) || (verifiedShare ? "查实占比" : `${dimension}构成`),
      );
      const node = document.createElement(chartTag);
      node.dataset.props = JSON.stringify(
        buildStaticChartModel(
          // Empty: slot caption already shows the title.
          "",
          tabId,
          grouped,
          {
            x: [{ field: "label", name: verifiedShare ? "查实占比" : dimension || "label" }],
            y: [{ field: "value", name: resolveCompositionYDisplayName(config, detail, "value") }],
          },
          config,
        ),
      );
      host.appendChild(node);
      dispatchPreviewUpdated("drilldown");
      return true;
    }
    if (explainMetricKind(config, tabId) === "trend") {
      const columns = Array.isArray(dataset?.columns) ? dataset.columns : [];
      const trendField = nonEmptyString(config?.trendField);
      if (!trendField) {
        recordPopupDebugIssue({
          level: "error",
          message: `趋势 tab 未解析到日期字段（tab=${normalizeTabId(tabId)}）`,
          phase: "derived_trend_field_missing",
          detail,
          config,
          datasetId,
          root,
        });
        return false;
      }
      const grouped = groupRowsByMonth(rows, trendField, columns);
      if (!grouped.length) return false;
      const registered = await ensureDrilldownChartRegistered("mei-chart-line");
      if (!registered) return false;
      resetDrilldownChartSlotHost(host, resolveDrilldownChartSlotCaption(config) || "趋势");
      const node = document.createElement("mei-chart-line");
      node.dataset.props = JSON.stringify(
        buildStaticChartModel(
          // Empty: slot caption already shows the title.
          "",
          tabId,
          grouped,
          {
            x: "month",
            y: "value",
          },
          config,
        ),
      );
      host.appendChild(node);
      dispatchPreviewUpdated("drilldown");
      return true;
    }
    return false;
  }



/* ===== spa-navigation/drilldown/render-generic.js ===== */
  function renderDrilldownContent(root, detail, config, tabId, hostOverride = null) {
    const activeConfig = resolveDrilldownTabConfig(config, tabId);
    applyDrilldownOverlayMeta(root, activeConfig);
    const host =
      hostOverride instanceof HTMLElement
        ? hostOverride
        : root.querySelector('[data-drilldown-table-host="true"]');
    if (!(host instanceof HTMLElement)) {
      return false;
    }
    const normalizedTab = normalizeTabId(tabId);
    if (config?.genericDrilldown) {
      const slot = config?.slotByTab?.[normalizedTab];
      if (slot?.component === "metric_card") {
        host.replaceChildren(createDrilldownSummaryNode(activeConfig, normalizedTab));
        setDrilldownOverlayStatus(root, "ready");
        return true;
      }
      if (slot?.component === "summary") {
        host.replaceChildren(createDrilldownSummaryNode(activeConfig, normalizedTab));
        setDrilldownOverlayStatus(root, "ready");
        return true;
      }
    }
    const kindTab = explainMetricKind(config, tabId);
    const tabOverride = config?.tabMetrics?.[normalizedTab] || config?.tabMetrics?.[kindTab];
    const hasCustomMetricSource = hasTabMetricDataSource(tabOverride);
    if (
      isDrilldownSummaryTab(tabId, config) ||
      (isDrilldownAnalysisTab(tabId, config) && !hasCustomMetricSource)
    ) {
      if (isDrilldownAnalysisTab(tabId, config) && !hasCustomMetricSource) {
        const summaryConfig = {
          ...activeConfig,
          note: nonEmptyString(activeConfig.note, unconfiguredTabNote(tabId)),
        };
        host.replaceChildren(createDrilldownSummaryNode(summaryConfig, tabId));
        setDrilldownOverlayStatus(root, "ready");
        return true;
      }
      host.replaceChildren(createDrilldownSummaryNode(activeConfig, tabId));
      setDrilldownOverlayStatus(root, "ready");
      return true;
    }
    if (isDrilldownAnalysisTab(tabId, config) || config?.genericDrilldown) {
      host.replaceChildren();
      setDrilldownOverlayStatus(root, "loading");
      const preferTableFirst =
        (config?.genericDrilldown && config?.slotByTab?.[normalizedTab]?.component === "data_table") ||
        (typeof window.__meiDatasetRuntime?.isYearMonthMatrixMetricConfig === "function" &&
          window.__meiDatasetRuntime.isYearMonthMatrixMetricConfig(activeConfig));
      const mountAnalysisContent = async () => {
        if (config?.genericDrilldown && config?.slotByTab?.[normalizedTab]?.supportRole === "composition") {
          if (await mountDerivedDrilldownContent(root, detail, activeConfig, tabId, host)) {
            return true;
          }
        }
        if (preferTableFirst && (await mountDrilldownTable(root, detail, activeConfig, host))) {
          return true;
        }
        if (await mountDrilldownChart(root, detail, activeConfig, tabId, host)) {
          return true;
        }
        if (!preferTableFirst && (await mountDrilldownTable(root, detail, activeConfig, host))) {
          return true;
        }
        if (config?.genericDrilldown && (await mountDerivedDrilldownContent(root, detail, activeConfig, tabId, host))) {
          return true;
        }
        return false;
      };
      mountAnalysisContent()
        .then(async (mounted) => {
          if (mounted) {
            setDrilldownOverlayStatus(root, "ready");
            dispatchPreviewUpdated("drilldown");
            return;
          }
          recordPopupDebugIssue({
            level: "error",
            message: `popup panel 表格挂载失败：${normalizedTab || tabId}`,
            phase: "table_mount_failed",
            detail,
            config: activeConfig,
            datasetId: activeConfig?.datasetId,
            metricId: activeConfig?.tableMetricId,
            root,
          });
          setDrilldownOverlayStatus(root, "error");
        })
        .catch(async (error) => {
          recordPopupDebugIssue({
            level: "error",
            message: String(error?.message || error || "图表 explain 块渲染失败"),
            phase: "chart_render_error",
            detail,
            config: activeConfig,
            datasetId: activeConfig?.datasetId,
            metricId: activeConfig?.tableMetricId,
            root,
            stack: error?.stack || "",
          });
          if (await mountDrilldownTable(root, detail, activeConfig, host)) {
            setDrilldownOverlayStatus(root, "ready");
            dispatchPreviewUpdated("drilldown");
            return;
          }
          setDrilldownOverlayStatus(root, "error");
        });
      return true;
    }
    setDrilldownOverlayStatus(root, "loading");
    mountDrilldownTable(root, detail, activeConfig, host)
      .then((mounted) => {
        if (mounted) {
          setDrilldownOverlayStatus(root, "ready");
          dispatchPreviewUpdated("drilldown");
          return;
        }
        recordPopupDebugIssue({
          level: "error",
          message: `popup panel 表格挂载失败：${normalizedTab || tabId}`,
          phase: "table_mount_failed",
          detail,
          config: activeConfig,
          datasetId: activeConfig?.datasetId,
          metricId: activeConfig?.tableMetricId,
          root,
        });
        setDrilldownOverlayStatus(root, "error");
      })
      .catch((error) => {
        recordPopupDebugIssue({
          level: "error",
          message: String(error?.message || error || "明细表渲染失败"),
          phase: "table_render_error",
          detail,
          config: activeConfig,
          datasetId: activeConfig?.datasetId,
          metricId: activeConfig?.tableMetricId,
          root,
          stack: error?.stack || "",
        });
        setDrilldownOverlayStatus(root, "error");
      });
    return true;
  }

  function renderDrilldownTabs(root, detail, config, hostOverride = null, contentHostOverride = null) {
    const tabsHost =
      hostOverride instanceof HTMLElement
        ? hostOverride
        : root.querySelector('[data-drilldown-tabs="true"]');
    if (!(tabsHost instanceof HTMLElement)) {
      return defaultActiveDrilldownTab(config?.tabs || []);
    }
    const normalizedTabs = Array.from(
      new Set(
        (Array.isArray(config?.tabs) ? config.tabs : [])
          .map((tab) => normalizeTabId(tab))
          .filter(Boolean),
      ),
    );
    const tabs = normalizedTabs.length
      ? normalizedTabs
      : [defaultActiveDrilldownTab(defaultDrilldownTabs(config?.explainKind, { hasDetail: true }))];
    const preferredTab = normalizeTabId(
      nonEmptyString(
        config?.popup?.entry,
        config?.popup?.entry_tab,
        config?.popup?.entryTab,
        config?.popup?.focus,
        config?.link?.entry,
        config?.link?.defaultFocus,
      ),
    );
    const defaultFromSlots = config?.genericDrilldown
      ? normalizeTabId(
          Object.values(config?.slotByTab || {}).find((slot) => slot?.default)?.id,
        )
      : "";
    const activeTab =
      (preferredTab && tabs.includes(preferredTab) ? preferredTab : "") ||
      (defaultFromSlots && tabs.includes(defaultFromSlots) ? defaultFromSlots : "") ||
      defaultActiveDrilldownTab(tabs);
    tabsHost.replaceChildren();
    tabsHost.toggleAttribute("hidden", tabs.length <= 1);
    tabs.forEach((tab) => {
      const explainMetric = explainMetricForTab(config, tab);
      const tabConfig = resolveDrilldownTabConfig(config, tab);
      const button = document.createElement("button");
      button.type = "button";
      button.className = "access-drilldown-tab-button";
      button.dataset.drilldownTab = tab;
      button.setAttribute("role", "tab");
      button.setAttribute("aria-selected", tab === activeTab ? "true" : "false");
      const slotLabel =
        config?.genericDrilldown && config?.slotByTab?.[tab]
          ? nonEmptyString(config.slotByTab[tab].label)
          : "";
      button.textContent = nonEmptyString(
        slotLabel,
        explainMetric?.label,
        tabConfig?.title,
        tabConfig?.label,
        drilldownTabLabel(explainMetric?.kind || tab, tabConfig),
      );
      button.addEventListener("click", () => {
        if (button.getAttribute("aria-selected") === "true") return;
        tabsHost
          .querySelectorAll(".access-drilldown-tab-button")
          .forEach((node) => node.setAttribute("aria-selected", node === button ? "true" : "false"));
        renderDrilldownContent(root, detail, config, tab, contentHostOverride);
      });
      tabsHost.appendChild(button);
    });
    return activeTab;
  }



/* ===== spa-navigation/drilldown/render-frame-t2-page.js ===== */
  async function composeBoardSceneSurface(appId, sceneId) {
    const ctx = {
      app_id: appId,
      appId,
      scene_id: sceneId,
      sceneId,
      surface: "app",
      mode: "app",
    };
    const result = await boot.viewRevisionClient?.negotiateWithLocalMiss?.(ctx, { silent: true });
    const layers = result?.assemble?.layers;
    if (!layers) {
      throw new Error("board scene layer assembly failed");
    }
    const temp = document.createElement("div");
    temp.setAttribute("data-mei-compose-placeholder", "1");
    const composeAxes =
      typeof boot.viewRevisionClient?.buildComposeRequest === "function"
        ? boot.viewRevisionClient.buildComposeRequest(ctx)
        : { review_projection: "live_full", data_mode: "eval", route_mode: "app" };
    const composed = boot.viewCompositor?.composeFromLayers?.(temp, layers, composeAxes);
    if (!composed) {
      throw new Error("board scene compose failed");
    }
    return (
      temp.querySelector("[data-mei-frame-viewport]") ||
      temp.querySelector(".preview-surface.preview-stage") ||
      temp.querySelector(".preview-surface")
    );
  }

  async function renderFrameBoardSceneContent(root, detail, config) {
    applyDrilldownOverlayMeta(root, config);
    setDrilldownOverlayStatus(root, "loading");
    const appId = resolvePreviewAppId();
    const sceneId = nonEmptyString(config?.boardSceneId, config?.sceneId);
    const host = root.querySelector('[data-drilldown-table-host="true"]');
    if (!appId || !sceneId || !(host instanceof HTMLElement)) {
      setDrilldownOverlayStatus(root, "error", {
        message: "frame 看板缺少 app、scene 或挂载节点",
        phase: "frame_board_setup",
        detail,
        config,
      });
      return false;
    }
    const url = `/apps/${encodeURIComponent(appId)}/${encodeURIComponent(sceneId)}`;
    try {
      if (!boot.viewRevisionClient?.negotiateWithLocalMiss || !boot.viewCompositor?.composeFromLayers) {
        throw new Error("board scene compose unavailable");
      }
      const surface = await composeBoardSceneSurface(appId, sceneId);
      if (!(surface instanceof HTMLElement)) {
        throw new Error("board scene preview surface missing");
      }
      host.replaceChildren();
      const mount = document.createElement("div");
      mount.className = "access-drilldown-frame-board-mount";
      mount.style.cssText =
        "width:100%;height:100%;min-height:320px;overflow:auto;box-sizing:border-box;";
      mount.appendChild(surface.cloneNode(true));
      host.appendChild(mount);
      setDrilldownOverlayStatus(root, "ready");
      dispatchPreviewUpdated("drilldown", { resetRuntimeQueryCache: false });
      if (typeof boot.scheduleFrameViewportRelayout === "function") {
        boot.scheduleFrameViewportRelayout();
      }
      return true;
    } catch (error) {
      recordPopupDebugIssue({
        level: "error",
        message: String(error?.message || error || "frame board scene mount failed"),
        phase: "frame_board_scene_mount",
        detail,
        config,
        root,
        stack: error?.stack || "",
      });
      setDrilldownOverlayStatus(root, "error");
      return false;
    }
  }


