      await boot.sceneManifestLoader.ensureLayers(
        missing,
        ctx.app_id || ctx.appId,
        ctx.scene_id || ctx.sceneId,
        { ...ctx, local_miss: true, signal: opts.signal },
        plan.manifest,
      );
      assemble = await tryAssembleLocal(ctx, plan, assembleOptions);
