    if (doc.overlay_defaults != null) {
      global.__mei.overlay_defaults = doc.overlay_defaults;
      global.__mei.t2_overlay_defaults = doc.overlay_defaults;
      global.__mei.page_overlay_defaults = doc.overlay_defaults;
    }
